var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        /**
        * universalni task pro administraci
        */
        function UniAdm_SetTask(task) {
            return window?.location?.href?.toLowerCase()?.includes("adx05") ? "ade-agendy" : task;
        }
        Pam.UniAdm_SetTask = UniAdm_SetTask;
        /**
        * universalni dialog
        * @param Title Název dialogu
        * @param ActionOK Akce pro tlacitko OK
        * @param ActionCLOSE_FormName Akce pro tlacitko CLOSE - nazev formulare
        */
        function UniAdm_DialogOptions(Title, ActionOK, ActionCLOSE_FormName) {
            return {
                title: Title,
                //autoMinWidth: true,
                width: 600,
                resizable: true,
                closeOnEscape: true,
                commandBar: [{ action: ActionOK, customClass: "g-button--primary" }, { action: UniAdm_CloseButton(ActionCLOSE_FormName) }]
            };
        }
        Pam.UniAdm_DialogOptions = UniAdm_DialogOptions;
        /**
        * universalni akce - close button
        * @param FormName nazev formulare
        * @param ActionName nazev akce (self)
        */
        function UniAdm_CloseButton(FormName = "", ActionName = "actClose") {
            return new GAction({
                name: ActionName, caption: "jres:32750006", icon: "", run: function (ev) {
                    let cnt = $.content(ev.currentTarget);
                    let form = $.content(ev.currentTarget).findForms(FormName);
                    if (form?.gform("hasChanged")) {
                        cnt.dialogs.confirm("Byly provedeny změny.</br> Opravdu zavřít?")
                            .on("yes", () => {
                            cnt.close();
                        });
                    }
                    else {
                        cnt.close();
                    }
                }
            });
        }
        Pam.UniAdm_CloseButton = UniAdm_CloseButton;
        /**
        * universalni kontrola dat
        * @param data kontrolovana data (objekt nebo pole objektu)
        * @param keys kontrolovane property na objektu (nejsou null)
        */
        function UniAdm_IsData(data, keys) {
            let result = false;
            if (data != undefined && data != null) {
                if (Array.isArray(data)) {
                    if (data.length > 0) {
                        if (keys === undefined || keys === null) {
                            result = true;
                        }
                        else {
                            result = (data.every((obj) => keys.every((key) => obj.hasOwnProperty(key) && obj[key] !== null)));
                        }
                    }
                }
                else {
                    if (Object.keys(data).length > 0) {
                        if (keys === undefined || keys === null) {
                            result = true;
                        }
                        else {
                            result = (keys != null && keys.every((key) => data.hasOwnProperty(key) && data[key] !== null));
                        }
                    }
                }
            }
            //TODO DEBUG: zaloguj klice, ktere na objektu nejsou! 
            return result;
        }
        Pam.UniAdm_IsData = UniAdm_IsData;
        /**
        * universalni formatovani
        * napr.: Pracovnik (ID_PRACOVNIK)
        * napr.: ID_PRACOVNIK - Pracovnik
        * @param id id
        * @param nazev nazev
        * @param zavorky ozavorkovat (nazev)
        * @coypright TV
        */
        function FormField_Format(id, nazev, zavorky = true) {
            const formattedNazev = nazev ?? "?";
            const formattedId = id ?? "?";
            return zavorky
                ? `${formattedNazev} (${formattedId})`
                : `${formattedId} - ${formattedNazev}`;
        }
        Pam.FormField_Format = FormField_Format;
        /**
         * universalni formatovani - template
         * style 1: {nazev} ({id})
         * style 2: {id} - {nazev}
         * style 3: {id} - {nazev} ({pid})
         * @param id id
         * @param nazev nazev
         * @param pid pid
         * @param style styl
         * @coypright TV
         */
        function FormField_Template(id, nazev, pid = undefined, style = 1) {
            const formattedId = id ?? "?";
            const formattedNazev = nazev ?? "?";
            const formattedPid = pid ?? "?";
            switch (style) {
                case 1:
                    return `{${formattedNazev}} ({${formattedId}})`;
                case 2:
                    return `{${formattedId}} - {${formattedNazev}}`;
                case 3:
                    return `{${formattedId}} - {${formattedNazev}} ({${formattedPid}})`;
                case 4:
                    return `{${formattedNazev}} ({${formattedId}})${pid ? `, {${pid}}` : ""}`;
                default:
                    return "";
            }
        }
        Pam.FormField_Template = FormField_Template;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
