            // Procházej zadané vlastnosti v objektu
            for (const prop of properties) {
                // Pokud není platný (null nebo undefined), vrať implicitní hodnotu
                if (aktualniObjekt == null)
                    return implicitniHodnota;
                // Přistup k další vlastnosti
                aktualniObjekt = aktualniObjekt[prop];
            }
            // Pokud je hodnota null nebo undefined, vrať implicitní hodnotu
            return aktualniObjekt != null ? aktualniObjekt : implicitniHodnota;
