        /**
        * Získání rok_obd_mzdy z textové prezentace
        * @param {number| string | null | undefined} rok_obd_text řetězec ve tvaru MM/RRRR MMRRRR MMRR MM:RRRR MM:RR MM-RRRR MM/RR MM*RRRR
        * @returns {number | null} 1/2024 => 24288
        * @author ZMOLIK
        */
        function RokObdMzdyTxt2RokObdMzdy(rok_obd_mzdy) {
            if (typeof rok_obd_mzdy === 'number') {
                if (rok_obd_mzdy > 22800 && rok_obd_mzdy < 35999) {
                    return rok_obd_mzdy;
                }
                else {
                    return null;
                } // pokud je to číslo a je to v rozsahu rok_obd_mzdy, tak to vrátím
            }
            if (rok_obd_mzdy == null)
                return null; // ošetření null nebo undefined
            const rok_obd_text = Pam.toString(rok_obd_mzdy);
            // Podporované formáty: MM/RRRR, MMRRRR, MMRR, MM:RRRR, MM:RR, MM-RRRR, MM/RR, MM*RRRR
            const match = rok_obd_text.trim().match(/^(\d{1,2})[\/:*\-]?(\d{2,4})$/);
            if (!match)
                return null; // neodpovídá žádnému podporovanému formátu
            const mesic = Number(match[1]);
            if (mesic < 1 || mesic > 12)
                return null; // chybný měsíc
            let rok = Number(match[2]);
            if (rok < 100)
                rok += 2000; // pokud je rok ve formátu RR, převedu na RRRR předpokládám 21. století
            if (rok < 1900 || rok > 2100)
                return null; // chybný rok
            return rok * 12 + mesic - 1;
        }
