        /**
         * otestování zdali je výslek spg procedury OK
         * @param {Gordic.Pam.Interface.GSplResultDto | null | undefined} spgresult normalizovaný spg result
         * @returns {boolean}
         */
        function CheckSpgOk(spgresult) {
            if (!spgresult)
                return false;
            const op_err_code = spgresult.op_err_code ?? 0;
            if (op_err_code < 0 && op_err_code > -100)
                return true; // specifické kódy využívám pro varování
            return (op_err_code === 0 && (spgresult.op_err_txt ?? "").trim() === ""); // null a "" je považováno za OK kvůli ORA    
        }
