        /**
         * Získání zásobníku volání jako řetězec
         * @returns {string} Zásobník volání
         */
        function getStack() {
            const stack = new Error().stack;
            if (!stack)
                return ""; // fallback, kdyby stack nebyl dostupný
            const lines = stack
                .split("\n")
                .map(line => line.trim())
                .filter(line => !line.startsWith("at Object.getStack")); // Odstranit všechny řádky, které začínají "at Object.getStack"
            return lines.join("\n");
        }
