        /**
        * @param {GContent} cnt content
        * @param {JQuery<HTMLElement> | string} obj HTML element představující grid nebo název elementu
        * @param {boolean} stopEditorOnError [true] zastavovat editor na chybách
        * @param {boolean} tocitko [true] zobrazovat točítko s progressem validace
        * @returns {Promise<GridEditorErrors>}
        */
        function GridEditorValidate(cnt, obj, stopEditorOnError = true, tocitko = true) {
            return new Promise((resolve, reject) => {
                const Content = cnt;
                let result = { valid: true, cell: [] };
                const grid = GridGetGrid(obj);
                const view = Pam.GridGetView(grid);
                const rows = view.getDataRows().length;
                const cols = grid.ggrid("trueColumns").length;
                let pocetChyb = 0;
                let opt = {
                    id: Pam.CreateGuid(),
                    progress: 0,
                    text: "Validuji",
                    total: rows * cols
                };
                if (tocitko)
                    Content.beginOperation(opt);
                let i = 0;
                let j = 0;
                function validateNextCell() {
                    try {
                        if (i >= rows) {
                            // Validace dokončena
                            if (stopEditorOnError && !result.valid) {
                                grid.ggrid("activeCellAddress", result.cell[0].coords);
                                grid.ggridcelleditor("start");
                                grid.ggrid("refreshErrors");
                            }
                            if (tocitko)
                                Content.endOperation(opt);
                            resolve(result);
                            return;
                        }
                        opt.progress = opt.progress++;
                        opt.text = `Validuji - řádek:${i + 1} sloupec ${j + 1}`;
                        if (tocitko)
                            Content.progressOperation(opt);
                        const coords = { row: i, col: j };
                        grid.ggrid("activeCellAddress", coords);
                        const chybyGridu = grid.findFields().gfield("validate").gfield("getErrors");
                        if (chybyGridu.length > 0) {
                            if (pocetChyb == 0) {
                                result.valid = false;
                            }
                            const allErrors = chybyGridu.map(err => err.message).join('\n');
                            result.cell[pocetChyb] = {
                                coords: coords,
                                error: allErrors
                            };
                            pocetChyb++;
                        }
                        // Přechod na další buňku
                        j++;
                        if (j >= cols) {
                            j = 0;
                            i++;
                        }
                        // Pokračování v další iteraci (asynchronně)
                        setTimeout(validateNextCell, 0);
                    }
                    catch (error) {
                        if (tocitko)
                            Content.endOperation(opt);
                        reject(error);
                    }
                }
                // Spuštění validace
                validateNextCell();
            });
        }
        Pam.GridEditorValidate = GridEditorValidate;
