        /**
         * Aktualizace dat v gridu ( pokud zde již jsou, tak provede jejich aktualizaci podle klíče)
         * @param {JQuery<HTMLElement> | string} obj HTML element představující grid nebo název elementu
         * @param {Object} dto Vkládaná data
         * @param {boolean} norefresh [false] v případě true zakáže aktualizaci gridu - implicitně vypnuto
         * @param {boolean} replace [false] v případě true neprovede aktualizaci, ale náhradu kompletním řádkem ( má smysl pouze pro UPDATE)
         * @returns {object} nalezený klíč
         */
        function GridInsertOrUpdate(obj, dto, norefresh = false, replace = false) {
            let view = GridGetView(obj); // získám si view
            let key = {};
            let klicView = view["keys"];
            $.each(klicView, function (index, k) {
                key[k] = dto[k];
                //(<any>key)[k] = dto[index][k];
            }); // a sestavím klíč
            let radkyGridu = view.getRows(); // získání řádků gridu
            let row = findRowByKey(radkyGridu, key); // nalezení konkrétního řádku v gridu podle klíče ( první, tj. klíč musí být zadán přesně)
            let data = row["data"];
            if (data != null) { // klíč nalezen => je možno dělat update
                if (replace) { // update, s nastavením všech hodnot podle zaslaného dto
                    view.updateData(dto, "update"); // aktualizuji view
                }
                else { // update se zachováním původních hodnot
                    var newRow = data; // původní hodnoty
                    Object.keys(dto).forEach(function (k) { newRow[k] = dto[k]; }); // nová data doplním do původního řádku
                    view.updateData(newRow, "update"); // aktualizuji view
                }
            }
            else {
                view.updateData(dto, "add"); // insert
            }
            GridSetData(obj, view, norefresh); // a aplikuji změnu na grid
            return key;
            //TODO metoda je nejspíš  opravená a lze použít příno view.updateData(newRow, "update"); // aktualizuji view
        }
