        /**
         * Získání maxima z pole
         * @param {object[]} data pole prvků
         * @param {string} itemName název sloupce
         * @returns {number | null} maximální hodnota (číslo), null pokud zde nic není
         */
        function MaxFromArray(data, itemName) {
            if (!data || data.length === 0) {
                return null;
            }
            let maximum = null;
            for (const item of data) {
                const value = item[itemName];
                if (typeof value === 'number' && !isNaN(value)) {
                    if (maximum === null || value > maximum) {
                        maximum = value;
                    }
                }
            }
            return maximum;
        }
        Pam.MaxFromArray = MaxFromArray;
        /**  Získání nejdelšího řetězce z pole
            * @param {object[]} data pole prvků
            * @param {string} itemName název sloupce
            * @returns {string | null} nejdelší řetězec, null pokud zde nic není
            */
        function MaxStringFromArray(data, itemName) {
            if (!data || data.length === 0) {
                return null;
            }
            let longest = null;
            let maxLength = 0;
            for (const item of data) {
                const value = item[itemName];
                if (typeof value === 'string') {
                    const length = value.length;
                    if (length > maxLength) {
                        maxLength = length;
                        longest = value;
                    }
                }
            }
            return longest;
        }
        Pam.MaxStringFromArray = MaxStringFromArray;
