var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        /**
        * Zapouzdření manipulace s daty
        */
        class DataObject {
            constructor(content, obj) {
                this._content = content;
                this._DataObj = obj;
            }
            /**
             * ISL objekt datového objektu
             * @returns
             */
            get IslObject() {
                return this._DataObj.IslObject;
            }
            /**
            * MessageBeginOperation
            * @returns
            */
            get MessageBeginOperation() {
                return this._DataObj.MessageBeginOperation;
            }
            /**
            * Titulek pro insert záznamu
            * @returns
            */
            get InsertTitle() {
                return this._DataObj.InsertTitle ? this._DataObj.InsertTitle : Gordic.Pam.DataType.InsertTitleDefault;
            }
            /**
            * Titulek pro editaci záznamu
            * @returns
            */
            get EditTitle() {
                return this._DataObj.EditTitle ? this._DataObj.EditTitle : Gordic.Pam.DataType.EditTitleDefault;
            }
            /**
            * Titulek pro editaci záznamu
            * @returns
            */
            get DeleteTitle() {
                return this._DataObj.DeleteTitle ? this._DataObj.DeleteTitle : Gordic.Pam.DataType.DeleteTitleDefault;
            }
            /**
            * List metoda
            * @returns
            */
            get ListMethod() {
                return (this._DataObj.MethodList) ? this._DataObj.MethodList : Gordic.Pam.DataType.MethodListDefault;
            }
            /**
            * Update metoda
            * @returns
            */
            get UpdateMethod() {
                return (this._DataObj.MethodUpdate) ? this._DataObj.MethodUpdate : Gordic.Pam.DataType.MethodUpdateDefault;
            }
            /**
            * Delete metoda
            * @returns
            */
            get DeleteMethod() {
                return (this._DataObj.MethodDelete) ? this._DataObj.MethodDelete : Gordic.Pam.DataType.MethodDeleteDefault;
            }
            /**
            * Create metoda
            * @returns
            */
            get CreateMethod() {
                return (this._DataObj.MethodCreate) ? this._DataObj.MethodCreate : Gordic.Pam.DataType.MethodCreateDefault;
            }
            /**
            * Read metoda
            * @returns
            */
            get ReadMethod() {
                return (this._DataObj.MethodRead) ? this._DataObj.MethodRead : Gordic.Pam.DataType.MethodReadDefault;
            }
            /**
            * Knt metoda
            * @returns
            */
            get KntMethod() {
                return (this._DataObj.MethodKnt) ? this._DataObj.MethodKnt : Gordic.Pam.DataType.MethodKntDefault;
            }
            /**
            * Access token metoda
            * @returns
            */
            get AccessMethod() {
                return (this._DataObj.MethodAccessToken) ? this._DataObj.MethodAccessToken : Gordic.Pam.DataType.MethodAccessToken;
            }
            /**
            * Získání dataKey
            * @returns
            */
            get dataKeyMethod() {
                return (this._DataObj.dataKey) ? this._DataObj.dataKey : "";
            }
            /**
             * Access token
             * @returns {JQueryPromise<Gordic.Pam.Interface.AccessTokenPamDto>} Promise s access tokenem nebo odmítnutím při chybě.
             */
            ACT() {
                const MainThis = this;
                const Content = this._content;
                const def = $.Deferred();
                Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.AccessMethod) // získání PAM AccessTokenu přes ISL
                    .done(function (result) {
                    def.resolve(result);
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise(); // vracím čekačku
            }
            /**
             * Read
             * @param {Gordic.Isl.GServiceReadRequest<any>} rq - Požadavek na načtení dat.
             * @returns {JQueryPromise<Object | null>} Promise s výsledkem načtení dat nebo null při chybě.
             */
            Read(rq) {
                const Content = this._content;
                const MainThis = this;
                const def = $.Deferred();
                this.ACT()
                    .done(function (result) {
                    let act = result;
                    if (!act.Read) { // pokud je zakázáno číst jdu ven
                        throw "Zakázán read objektu: " + MainThis.IslObject;
                        //def.reject(null);
                    }
                    Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.ReadMethod, rq).getData()
                        .done(function (result) {
                        const key = (MainThis.dataKeyMethod) ? MainThis.dataKeyMethod : "";
                        const view = (key) ? new Gordic.Data.View(result["data"], { key: key }) : new Gordic.Data.View(result["data"]);
                        def.resolve(view);
                    })
                        .fail(function () {
                        def.reject(null);
                    });
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise(); // // GServiceReadResponse;            
            }
            /**
            * List
            * @param { Gordic.Isl.GServiceListRequest } rq - Požadavek na načtení seznamu dat.
            * @returns { JQueryPromise<Object | null> } Promise s výsledkem načtení dat nebo null při chybě.
            */
            List(rq) {
                const Content = this._content;
                const MainThis = this;
                const def = $.Deferred();
                this.ACT()
                    .done(function (result) {
                    let act = result;
                    if (!act.Read) { // pokud je zakázáno číst jdu ven
                        throw "Zakázán list objektu: " + MainThis.IslObject;
                        //def.reject();
                    }
                    Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.ListMethod, rq) //.getData()                    
                        .done(function (result) {
                        const key = (MainThis._DataObj?.dataKey) ? MainThis._DataObj.dataKey : null;
                        const view = (key) ? new Gordic.Data.View(result["data"], { key: key }) : new Gordic.Data.View(result["data"]);
                        def.resolve(view);
                    })
                        .fail(function () {
                        def.reject(null);
                    });
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise();
            }
            /**
             * Insert
             * @param {Gordic.Isl.GServiceSaveRequest<any>} rq - Požadavek na vložení nového záznamu.
             * @returns {JQueryPromise<Object | null>} Promise s výsledkem vložení nebo null při chybě.
             */
            Insert(rq) {
                const Content = this._content;
                const MainThis = this;
                const def = $.Deferred();
                this.ACT()
                    .done(function (result) {
                    let act = result;
                    if (!act.Create) { // pokud je zakázáno zakládat nový záznam
                        throw "Zakázán create: " + MainThis.IslObject;
                        //def.reject();
                    }
                    Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.CreateMethod, rq)
                        //Gordic.Pam.Isl(MainThis._uniqueID, "create", { Data: dto })
                        .done(function (result) {
                        def.resolve(result);
                    })
                        .fail(function () {
                        def.reject(null);
                    });
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise(); // // GServiceReadResponse;            
            }
            /**
             * Update
             * @param {Gordic.Isl.GServiceSaveRequest<any>} rq - Požadavek na aktualizaci záznamu.
             * @returns {JQueryPromise<Object | null>} Promise s výsledkem aktualizace nebo null při chybě.
             */
            Update(rq) {
                const Content = this._content;
                const MainThis = this;
                const def = $.Deferred();
                this.ACT()
                    .done(function (result) {
                    let act = result;
                    if (!act.Update) { // pokud je zakázáno číst jdu ven
                        throw "Zakázán update: " + MainThis.IslObject;
                        //def.reject();
                    }
                    //Gordic.Pam.Isl(MainThis._uniqueID, "update", { Data: dto })
                    Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.UpdateMethod, rq)
                        .done(function (result) {
                        def.resolve(result);
                    })
                        .fail(function () {
                        def.reject(null);
                    });
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise(); // // GServiceReadResponse;            
            }
            /**
             * Delete
             * @param {Gordic.Isl.GServiceSaveRequest<any>} rq - Požadavek na smazání záznamu.
             * @returns {JQueryPromise<Object | null>} Promise s výsledkem smazání nebo null při chybě.
             */
            Delete(rq) {
                const Content = this._content;
                const MainThis = this;
                const def = $.Deferred();
                this.ACT()
                    .done(function (result) {
                    let act = result;
                    if (!act.Delete) { // pokud je zakázáno rušit
                        throw "Zakázán delete: " + MainThis.IslObject;
                        //def.reject();
                    }
                    //Gordic.Pam.Isl(MainThis._uniqueID, "delete", { Data: dto })
                    Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.DeleteMethod, rq)
                        .done(function (result) {
                        def.resolve(result);
                    })
                        .fail(function () {
                        def.reject(null);
                    });
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise(); // // GServiceReadResponse;            
            }
            /**
             * Kontrola dat
             * @param {Object} dto - Vstupní data pro operaci KNT.
             * @returns {JQueryPromise<Object | null>} Promise s výsledkem operace nebo null při chybě.
             */
            Knt(dto) {
                const Content = this._content;
                const MainThis = this;
                const def = $.Deferred();
                Gordic.Pam.Isl(Content, MainThis.IslObject, MainThis.KntMethod, { dto })
                    .done(function (result) {
                    def.resolve(result);
                })
                    .fail(function () {
                    def.reject(null);
                });
                return def.promise();
            }
        }
        Pam.DataObject = DataObject;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
