                // char_3+char_4 slouží jako data pro combo2 a  char_4+char_5 slouží jako data pro combo3
                //Jejich prvnotní naplnění se řídí podle první položky prvního combo
                const field2Data = (field1Data.length == 0) ? [] : Pam.arrReduceToUniq(Pam.arrSubArrayByKeys(convertedArray, field1Data[0]), "char_3,char_4");
                const field3Data = (field2Data.length == 0) ? [] : Pam.arrReduceToUniq(Pam.arrSubArrayByKeys(convertedArray, { char_1: field1Data[0].char_1, char_2: field1Data[0].char_2, char_3: field2Data[0].char_3, char_4: field2Data[0].char_4 }), "char_5,char_6");
                // options
                // jako základ si vezmu to bylo posláno
