                if (field1Data.length > 0)
                    opt1.initialValue = field1Data[0]; // pokud mám nějaká data, tak je předplním
                opt2.itemTemplate = "{char_3:trim:encode}";
                opt2.graphicInput = "hidden";
                opt2.dropdown = true;
                opt2.data = field2Data;
