                if (field3Data.length > 0)
                    opt3.initialValue = field3Data[0]; // pokud mám nějaká data, tak je předplním
                opt1.change = (ev, input) => {
                    const POLE1_HODNOTA = (input.value != null) ? { char_1: input.value["char_1"], char_2: input.value["char_2"], } : { char_1: "", char_2: "" };
                    const POLE2_HODNOTY = Pam.arrReduceToUniq(Gordic.Pam.arrSubArrayByKeys(convertedArray, POLE1_HODNOTA), "char_3,char_4");
                    const POLE2 = $(ev.currentTarget).gform().findFields(fieldOpt2.name);
                    POLE2.gfield("clear");
                    if (POLE2_HODNOTY.length > 0) {
                        POLE2.gfield("option", { data: POLE2_HODNOTY }).gfield("setValue", POLE2_HODNOTY[0]);
                    }
                    POLE2.gfield("option", { disabled: POLE2_HODNOTY.length < 2 });
                    if (orinalChangeCombo1 != null) { // zavolání původní události change neboť jsem ji přepsal
                        orinalChangeCombo1.call(ev.target, ev, { value: input.value, flags: input.flags });
                    }
                };
                opt2.change = (ev, input) => {
                    const POLE2_HODNOTA = (input.value != null) ? { char_3: input.value["char_3"], char_4: input.value["char_4"], } : { char_3: "", char_4: "" };
                    const POLE3_HODNOTY = Pam.arrReduceToUniq(Gordic.Pam.arrSubArrayByKeys(convertedArray, POLE2_HODNOTA), "char_5,char_6");
                    const POLE3 = $(ev.currentTarget).gform().findFields(fieldOpt3.name);
                    POLE3.gfield("clear");
                    if (POLE3_HODNOTY.length > 0) {
                        POLE3.gfield("option", { data: POLE3_HODNOTY }).gfield("setValue", POLE3_HODNOTY[0]);
                    }
                    POLE3.gfield("option", { disabled: POLE3_HODNOTY.length < 2 });
                    if (orinalChangeCombo2 != null) { // zavolání původní události change neboť jsem ji přepsal
                        orinalChangeCombo2.call(ev.target, ev, { value: input.value, flags: input.flags });
                    }
                };
                return new Gordic.Forms.Form()
                    .addRow(rowOptionsInternal)
                    .addField("gselectbox", "w-4", opt1)
                    .addField("gselectbox", "w-4", opt2)
                    .addField("gselectbox", "w-4", opt3)
