/**
 * Inteligentní cache pro PAM
 *
 * @author ZMOLIK
 * @description PAM_CACHE slouží k uložení přihlašocvaích údajů a dalších globálních proměnných
 *  které jsou potřebné pro běh aplikace.
 * Proměnné
 * rokobdlogin - období přihlášené v aplikaci
 * licAdr - licence databáze
 * ixs_vaj - indetifikace uzávěrkové jednotky
 * typInst - typ instalace
 *
 * Jsou načítány při přihlášení do aplikace a jsou dostupné v celém běhu aplikace. Neměly by se ručně měnit!!
 * Vlastní plnění těchto proměnných je zajištěno v 016_Gordic.Pam.Init.ts
 */
var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        class Cache {
            constructor() {
                this._prefix = "PAM";
                if (!Gordic.Pam.Cache.instance) {
                    this._gstore = new Gordic.Data.Storage();
                }
            }
            // Statická metoda pro získání jediné instance třídy
            static getInstance() {
                if (!Gordic.Pam.Cache.instance) {
                    Gordic.Pam.Cache.instance = new Gordic.Pam.Cache();
                }
                return Gordic.Pam.Cache.instance;
            }
            /**
             * získání obsahu cache PAM - hodí se hlavně pro ladící účely
             * */
            get data() {
                // return Gordic.Pam.Cache.instance._gstore.get(this._prefix);
                const baseData = Gordic.Pam.Cache.instance._gstore.get(this._prefix);
                const rokobdlogin = Gordic.Pam.Cache.instance.rokobdlogin;
                const licAdr = Gordic.Pam.Cache.instance.licAdr;
                const ixs_vaj = Gordic.Pam.Cache.instance.ixs_vaj;
                const typInst = Gordic.Pam.Cache.instance.typInst;
                return {
                    ...baseData,
                    rokobdlogin,
                    licAdr,
                    ixs_vaj,
                    typInst
                };
            }
            /**
             * Získání globální proměnných
             *  @param force Vynucení načtení ze serveru, tj. nezkouší se cache
             *
             *  @description Nejprve prohlédne cache a pokud nenalezne, tak získá nastavení globálních proměnných ze serveru a opětovně uloží do cache.
             *  Při dalším čtení je již bráno s cache. Vynucením "force" lze říci, že cache se má ignorovat
             * */
            getglobal(force = false) {
                const store = Gordic.Pam.Cache.instance._gstore;
                const keyname = `${this._prefix}.global`;
                // Získání hodnoty z cache
                let result = !force ? this.get(keyname) : null;
                // Pokud hodnota není v cache nebo bylo požadováno její načtení ze serveru
                if (!result || force) {
                    return Gordic.Pam.CallWithPromise("PamGlob") // Načtení globálních proměnných ze serveru
                        .then((result) => {
                        store.set(keyname, result); // Uložení do úložiště
                        return result; // Vrácení výsledku
                    })
                        .catch(() => {
                        store.set(keyname, null); // Uložení prázdné hodnoty při selhání
                        return Promise.reject(null); // Zamítnutí promise s null
                    });
                }
                else {
                    // Hodnota nalezena v cache, vracíme ji přímo
                    return Promise.resolve(result);
                }
            }
            /**
              * Získání hodnoty parametru
              *  @param param programátorský kód parametru
              *  @param force Vynucení načtení ze serveru, tj. nezkouší se cache
              *
              *  @description Nejprve prohlédne cache a pokud nenalezne, tak získá aktuální nastavení parametru ze serveru a opětovně uloží do cache.
              *  Při dalším čtení je již bráno s cache. Vynucením "force" lze říci, že cache se má ignorovat
              * */
            getparam(param, force = false) {
                const store = Gordic.Pam.Cache.instance._gstore;
                const keyname = `${this._prefix}.${param}`;
                // Získání hodnoty z cache, pokud není vynucené načtení ze serveru
                let result = !force ? Gordic.Pam.Cache.instance.get(keyname) : null;
                // Pokud není hodnota v cache nebo je vynuceno načtení ze serveru
                if (!result || force) {
                    return Gordic.Pam.CallWithPromise("GetParametr", { param: param })
                        .then((result) => {
                        store.set(keyname, result); // Uložení do úložiště
                        return result; // Vrácení výsledku
                    })
                        .catch(() => {
                        store.set(keyname, null); // Uložení prázdné hodnoty při selhání
                        return Promise.reject(null); // Zamítnutí promise s hodnotou null
                    });
                }
                else {
                    // Pokud je hodnota nalezena v cache, vrátíme ji přímo
                    return Promise.resolve(result);
                }
            }
            /**
             * Získává hodnotu z cache na základě zadaného názvu položky (`itemName`).
             * Umožňuje vrátit konkrétní typ hodnoty pomocí generického typu `T`.
             *
             * @param {string} itemName - Název položky, kterou chcete získat.
             * @returns {T | null} - Vrací hodnotu dané položky typu `T`, nebo `null`, pokud položka neexistuje.
             * @template T - Generický typ, který určuje typ vracené hodnoty.
             *
             * @example
             * // Příklad použití:
             * const licAdr = cache.get<string>("licAdr");
             */
            get(itemName) {
                switch (itemName) {
                    case "ixs_vaj":
                        return Gordic.Pam.Cache.instance.ixs_vaj;
                    case "licAdr":
                        return Gordic.Pam.Cache.instance.licAdr;
                    case "typInst":
                        return Gordic.Pam.Cache.instance.typInst;
                    case "rokobdlogin":
                        return Gordic.Pam.Cache.instance.rokobdlogin;
                    default:
                        return Gordic.Pam.Cache.instance._gstore.get(`${this._prefix}.${itemName}`);
                }
            }
            set(itemName, value) {
                switch (itemName) {
                    case "ixs_vaj":
                        Gordic.Pam.Cache.instance.ixs_vaj = value;
                        break;
                    case "licAdr":
                        Gordic.Pam.Cache.instance.licAdr = value;
                        break;
                    case "typInst":
                        Gordic.Pam.Cache.instance.typInst = value;
                        break;
                    case "rokobdlogin":
                        Gordic.Pam.Cache.instance.rokobdlogin = value;
                        break;
                    default:
                        Gordic.Pam.Cache.instance._gstore.set(`${this._prefix}.${itemName}`, value);
                }
            }
        }
        Pam.Cache = Cache;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
// globální úložiště PAM - !! pouze jedna instance!!, která je zakládána implicitně formou Singletonu
const PAM_CACHE = Gordic.Pam.Cache.getInstance();
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
