var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        // Typy zobrazení chybových hlášení
        let TypyZobrazeniChyb;
        (function (TypyZobrazeniChyb) {
            TypyZobrazeniChyb["ikona_char_123"] = "ikona_char_123";
            TypyZobrazeniChyb["ikona_oblast_text"] = "ikona_oblast_text"; // ikona, oblast a text
        })(TypyZobrazeniChyb = Pam.TypyZobrazeniChyb || (Pam.TypyZobrazeniChyb = {}));
        class Forms {
            constructor(content) {
                this._content = content;
            }
            //#endregion
            /**
            * Nastaví libovolnou option dialogu
            * @param frm formulář nebo element dialogu
            * @param option název option (např. "title", "modal", "width", "height")
            * @param value hodnota option
            * @example
            * // Nastavení titulku
            * Pam.Forms.SetOption(frm, "title", "Nový titulek");
            *
            * // Nastavení modálního režimu
            * Pam.Forms.SetOption(frm, "modal", true);
            *
            * // Nastavení šířky dialogu
            * Pam.Forms.SetOption(frm, "width", 500);
            */
            static SetOption(frm, option, value) {
                if (!frm)
                    return;
                const $dialog = $(frm);
                $dialog.dialog("option", option, value);
            }
            /**
            * Zpracuje výsledek SPG procedury a extrahuje extra_data
                *
                * @param cnt Kontext obsahu (GContent) pro aktualizaci progress operace
                * @param spg_result Výsledek volání SPG procedury obsahující data a případné chyby
                * @param op Objekt s informacemi o probíhající operaci (progress, text)
                * @returns Pole GPamtpomDto objektů pokud existují extra_data, jinak null
                * @throws Vyhodí spg_result pokud SPG procedura skončila chybou
            */
            static spg2ExtraData(cnt, spg_result, op) {
                if (cnt) {
                    if (op.progress != null)
                        op.progress++; // existuje-li čítač
                    op.text = 'Vyhodnocuji výsledky';
                    cnt.progressOperation(op);
                }
                if (!Pam.CheckSpgOk(spg_result)) { // kontola výsledků spg_procedury
                    throw spg_result;
                }
                return Array.isArray(spg_result?.extra_data) ? spg_result.extra_data : null; // jsou-li extra_data vrátím k dalšímu zpracování
            }
            /**
             * Vytvoření okna pomocí frm
             * @param frm formulář
             * @param optDialog vlastnosti dialogu
             * @param cnt content, pokud není zadán, tak se vytvoří
             * @param data data, která se předávají do formuláře a po jeho vytvoření jsou nastavena do formuláře pomocí apply
             */
            WindowFromFrm(frm, optDialog, cnt, data) {
                const opt = optDialog ?? { width: window.innerWidth - 50, height: window.innerHeight - 50 };
                const Content = this._content ?? cnt ?? GContent.createContent();
                const div = $("<div>").prop("doRemoveOnClose", true).gform("createFrom", frm);
                if (data) {
                    div.findForms().findFields().gfield("model", "apply", data);
                }
                return Content.dialogs.showWindow(div, null, opt);
            }
            /**
            * Vytvoření MODÁLNÍHO - okna pomocí frm
            * @param frm formulář
            * @param optDialog vlastnoti dialogu
            * @param cnt content, pokud není zadán, tak se vytvoří
            * @param data data, která se předávají do formuláře a po jeho vytvoření jsou nastavena do formuláře pomocí apply
            */
            WindowFromFrmModal(frm, optDialog, cnt, data) {
                const opt = optDialog ?? { width: window.innerWidth - 50, height: window.innerHeight - 50 };
                const Content = this._content ?? cnt ?? GContent.createContent();
                const div = $("<div>").prop("doRemoveOnClose", true).gform("createFrom", frm);
                if (data) {
                    div.findForms().findFields().gfield("model", "apply", data);
                }
                if (opt.autofocusedField) { // pokud je zadáno, nastaví se focus na dané pole
                    div.findForms().findFields().findFields(opt.autofocusedField).gfield('focus');
                }
                return Content.dialogs.showModalWindow(div, null, opt);
            }
            /**
            * Vytvoření tabu pomocí DIVu nebo Formu
            * @param obj div nebo Form
            * @param uid uid
            * @param text text breadCrumbs
            * @param cnt content, pokud není zadán, tak se vytvoří
            */
            NewBreadCrumb(obj, uid, text = 'newBreadCrumb', type, cnt) {
                const Content = (this._content !== undefined) ? this._content : (cnt === undefined) ? GContent.createContent() : cnt;
                const circularReferenceReplacer = () => {
                    const seen = new WeakSet();
                    return (key, value) => {
                        if (typeof value === 'object' && value !== null) {
                            if (seen.has(value)) {
                                return undefined; // Ignore circular reference
                            }
                            seen.add(value);
                        }
                        return value;
                    };
                };
                const textObj = JSON.stringify(obj, circularReferenceReplacer(), 2);
                Content.navigate("Gordic.Pam.WebControls.Controls.Forms.GNewBreadbrumb", { uid: uid, obj: textObj, type: type, text_breadcrumbs: text });
            }
            /**
           * Čekací dialog - zobrazí dialog pokud je condition true, jinak vrátí false a dialog se nezobrazí.
           * @param condition logický výraz - pokud je false, vrátí se false bez dialogu
           * @param title titulek dialogu pokud je dialog zobrazen
           * @param html text dialogu pokud je dialog zobrazen
           * @param width šířka (pokud není zadána, vypočítá se podle textu)
           * @param height výška (pokud není zadána, vypočítá se podle textu)
           * @returns Promise<boolean> vrací výsledek volby uživatele z dialogu nebo false
           */
            WaitForOK(condition, title, html, width, height) {
                return new Promise((resolve, reject) => {
                    try {
                        if (!condition) {
                            resolve(false);
                            return;
                        } // Pokud je condition false, vrať false bez dialogu
                        const content = this._content ?? GContent.createContent();
                        const [calculatedWidth, calculatedHeight] = this.calculateDimensions(html, width, height);
                        const dialog = content.dialogs.messageBox(title, html, GDlg.mbbYesNo, GDlg.mbiQuestion, calculatedWidth, calculatedHeight);
                        dialog.on("close", (ev, result, args) => {
                            resolve(result === "yes");
                        });
                    }
                    catch (error) {
                        reject(error);
                    }
                });
            }
            /**
            * MessageBox s možností navázat formou promisse - velikost je tvořena dynamicky podle velikosti textu
            * @param title  titulek dialogu
            * @param html  text dialogu
            * @param width  šířka (pokud není zadána, vypočítá se podle textu)
            * @param height výška (pokud není zadána, vypočítá se podle textu)
            */
            MessageBox(title, html, width, height) {
                return new Promise((resolve, reject) => {
                    try {
                        const [calculatedWidth, calculatedHeight] = this.calculateDimensions(html, width, height);
                        const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                        const dialog = Content.dialogs.messageBox(title, html, [GDlg.mbbOk], Gordic.Pam.Icons.prazdno, calculatedWidth, calculatedHeight);
                        dialog.on("close", (ev, o, args) => {
                            resolve(true);
                        });
                    }
                    catch (error) {
                        reject(error);
                    }
                });
            }
            /**
            *
            * Zobrazí dialog s chybou, včetně detailních informací - rozpoznává i typ dialogu
            * @param error zachycená chyba, která se má zobrazit
            * @param title titulek dialogu
            * @param errorCode jedninečný kód chyby, který se zobrazí ( pokud je zadán)
            */
            ExceptionWindow(error, title, errorCode) {
                const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                const maintText = `${title} ${(errorCode) ? `[${errorCode}] ` : ""}`;
                const objectType = Pam.objectType(error);
                const povolitCopyToClipboard = true;
                let clipboardText = `${maintText}\n`;
                const form = new Gordic.Forms.Form({ name: "frmException", layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" })
                    .addSection()
                    .addRow()
                    .addText(`<i class="fa ${Pam.Icons.dialog_error} aria-hidden="true"></i><h2>${maintText}</h2>`)
                    .addRow("");
                let useDefault = false; // pokud není typ rozpoznán, použije se defaultní zobrazení
                const menuBar = [];
                const commandBar = [{ customClass: "g-button--primary", caption: "Zavřít", action: Pam.Actions.dlgCancelAct(false), favorite: true, primary: true }];
                let width = 800; // Výchozí šířka dialogu
                let height = 250; // Výchozí výška dialogu
                switch (objectType) {
                    case "string":
                        if (error === Pam.Forms.DIALOG_KNT_CANCEL)
                            return; // zavření dialogu s chybami uživatelem, nejedná se o chybu, v tomto případě se nic nezobrazí
                        form.addText(`${Pam.toString(error)}`);
                        clipboardText += `${Pam.toString(error)}`;
                        break;
                    case "Error":
                        const errorInfo = error;
                        form.addText(`${Pam.toString(errorInfo.message)}`);
                        if (errorInfo.stack) {
                            commandBar.push({
                                favorite: true, align: "opposite",
                                action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", Pam.toString(errorInfo.stack));
                                    }
                                }),
                            });
                        }
                        clipboardText += `${Pam.toString(errorInfo.message)}\n` + `${Pam.toString(errorInfo.stack)}`;
                        break;
                    case "GError":
                        const gerrorInfo = error;
                        form.addText(`${Pam.toString(gerrorInfo.message)}`);
                        if (gerrorInfo.stack) {
                            commandBar.push({
                                favorite: true, align: "opposite",
                                action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", Pam.toString(gerrorInfo.stack));
                                    }
                                }),
                            });
                        }
                        if (gerrorInfo.completeMessage) {
                            menuBar.push({
                                favorite: false,
                                action: new GAction({
                                    name: "stack", caption: "completeMessage", run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("stackTrace", Pam.toString(gerrorInfo.completeMessage));
                                    }
                                })
                            });
                        }
                        if (!Pam.isEmpty(gerrorInfo.data)) {
                            menuBar.push({
                                favorite: false,
                                action: new GAction({
                                    name: "data", caption: "data", run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("stackTrace", JSON.stringify(Pam.dumpObj(gerrorInfo.data)));
                                    }
                                })
                            });
                        }
                        clipboardText += `${Pam.toString(gerrorInfo.message)}\n` + `${Pam.toString(gerrorInfo.stack)}\n` + `${Pam.toString(gerrorInfo.completeMessage)}\n` + `${JSON.stringify(Pam.dumpObj(gerrorInfo.data))}`;
                        break;
                    case "GServerError":
                        const serverError = error;
                        const serverErrorBaseMsg = Pam.toString(serverError.details.baseMessage ?? serverError.message);
                        form.addText(`${serverErrorBaseMsg}`);
                        if (serverError.completeMessage) {
                            commandBar.push({
                                favorite: true, align: "opposite", action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", Pam.toString(serverError.completeMessage));
                                    }
                                })
                            });
                        }
                        clipboardText += `${Pam.toString(serverErrorBaseMsg)}\n` + `${Pam.toString(serverError.completeMessage)}`;
                        break;
                    case "IGExceptionInfo":
                        const excInfo = error;
                        form.addText(`${Pam.toString(excInfo.baseMessage)}`);
                        if (excInfo.completeMessage) {
                            commandBar.push({
                                favorite: true, align: "opposite",
                                action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", Pam.toString(excInfo.completeMessage));
                                    }
                                }),
                            });
                        }
                        if (excInfo.stackTrace) {
                            menuBar.push({
                                favorite: false,
                                action: new GAction({
                                    name: "stackTrace", caption: "stackTrace", run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("stackTrace", Pam.toString(excInfo));
                                    }
                                })
                            });
                        }
                        if (excInfo.longMessage) {
                            menuBar.push({
                                favorite: false,
                                action: new GAction({
                                    name: "longMessage", caption: "longMessage", run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("longMessage", Pam.toString(excInfo.longMessage));
                                    }
                                })
                            });
                        }
                        clipboardText += `${Pam.toString(excInfo.baseMessage)}\n` + `${Pam.toString(excInfo.completeMessage)}\n` + `${Pam.toString(excInfo.stackTrace)}\n` + `${Pam.toString(excInfo.longMessage)}`;
                        break;
                    case "GReportGenerateAsyncRejection":
                        const excReportGenerate = error;
                        form.addText(`${Pam.toString(excReportGenerate.exception?.message)}`);
                        if (excReportGenerate.exception?.completeMessage) {
                            commandBar.push({
                                favorite: true, align: "opposite",
                                action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", Pam.toString(excReportGenerate.exception?.completeMessage));
                                    }
                                }),
                            });
                        }
                        clipboardText += `${Pam.toString(excReportGenerate.exception?.message)}\n` + `${Pam.toString(excReportGenerate.exception?.completeMessage)}`;
                        break;
                    case "IGExceptionInfoMinimal":
                        const excInfoMin = error;
                        form.addText(`${Pam.toString(excInfoMin.message)}`);
                        if (excInfoMin.completeMessage) {
                            commandBar.push({
                                favorite: true, align: "opposite",
                                action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", Pam.toString(excInfoMin.completeMessage));
                                    }
                                }),
                            });
                        }
                        clipboardText += `${Pam.toString(excInfoMin.message)}\n` + `${Pam.toString(excInfoMin.completeMessage)}`;
                        break;
                    case "GSplResultDto":
                        const splResult = error;
                        form.addText(`${Pam.toString(splResult.op_err_txt).replace(/^# /, "")}`);
                        if (splResult.op_err_code) {
                            commandBar.push({
                                favorite: true, align: "opposite",
                                action: new GAction({
                                    name: "detail", caption: "Podrobnosti", icon: Pam.Icons.dialog_error_detail, run: (ev, ctx) => {
                                        const cnt = $.content(ev.currentTarget);
                                        new Gordic.Pam.Forms(cnt).MessageBox("Podrobnosti k chybě", `<b>err_code:</b> ${Pam.toString(splResult.op_err_code)}
                                             <b>err_sql:</b> ${Pam.toString(splResult.op_err_sql)}
                                             <b>err_isam:</b> ${Pam.toString(splResult.op_err_isam)}
                                             <b>err_txt:</b> ${Pam.toString(splResult.op_err_txt)}
                                             <b>err_lok:</b> ${Pam.toString(splResult.op_err_lok)}`, 800, 300);
                                    }
                                })
                            });
                        }
                        clipboardText += `err_code: ${Pam.toString(splResult.op_err_code)}\n` +
                            `err_sql: ${Pam.toString(splResult.op_err_sql)}\n` +
                            `err_isam: ${Pam.toString(splResult.op_err_isam)}\n` +
                            `err_txt: ${Pam.toString(splResult.op_err_txt)}\n` +
                            `err_lok: ${Pam.toString(splResult.op_err_lok)}\n`;
                        break;
                    default: // Pokud není typ rozpoznán, použijeme obecnou metodu
                        useDefault = true;
                        break;
                }
                if (useDefault) {
                    Content.dialogs.showException(error);
                }
                else {
                    if (povolitCopyToClipboard) {
                        const stack = Pam.getStack();
                        clipboardText += '\n\n' + stack; // přidám i stack volání ExceptionWindow pro lepší dohledání místa vzniku chyby
                        console.error("CHYBA:" + clipboardText);
                        clipboardText += '\n\n' + Pam.dumpObj2String(PAM_CACHE.data); // přidám i obsah PAM_CACHE pro lepší dohledání místa vzniku chyby
                        commandBar.push({ favorite: true, align: "opposite", caption: "", action: Pam.Actions.copyToClipboard(clipboardText) }); // unshift => přidá na začátek pole 
                    }
                    const dialogOptions = {
                        width: width, height: height, menuBar: (menuBar.length > 0) ? menuBar : undefined, commandBar: commandBar,
                    };
                    Gordic.Pam.Forms.prototype.WindowFromFrmModal(form, dialogOptions, Content);
                }
            }
            /**
             * Vypočítá rozměry dialogu podle obsahu
             * @param html obsah dialogu
             * @param width zadaná šířka
             * @param height zadaná výška
             * @returns [width, height]
             */
            calculateDimensions(html, width, height) {
                // Pokud jsou oba rozměry zadané, vrať je
                if (width !== undefined && height !== undefined) {
                    return [width, height];
                }
                // Konstanty pro výpočty
                // Získej rozměry viewportu
                const viewportWidth = window.innerWidth;
                const viewportHeight = window.innerHeight;
                // Dynamické konstanty podle velikosti viewArea
                const MIN_WIDTH = Math.max(200, viewportWidth * 0.15); // Minimální šířka v pixelech.Okno nebude nikdy užší než .. min 200px nebo 15% viewportu
                const MAX_WIDTH = Math.min(800, viewportWidth * 0.85); // Maximální šířka v pixelech. Okno nebude nikdy širší než ..max 800px nebo 85% viewportu
                const MIN_HEIGHT = Math.max(150, viewportHeight * 0.15); // Minimální výška v pixelech. Okno nebude nikdy nižší než .. min 150px nebo 15% viewportu
                const MAX_HEIGHT = Math.min(600, viewportHeight * 0.8); // Maximální výška v pixelech. Okno nebude nikdy vyšší než .. max 600px nebo 80% viewportu
                // Vnitřní odsazení (padding) v pixelech. Prostor mezi okrajem okna a obsahem 
                const PADDING = Math.max(20, Math.min(40, viewportWidth * 0.02)); // 20-40px podle šířky
                // Výška oblasti pro tlačítka přizpůsobená viewportu
                const BUTTON_AREA_HEIGHT = Math.max(60, Math.min(100, viewportHeight * 0.08)); // 60-100px
                let calculatedWidth = width;
                let calculatedHeight = height;
                // Vytvoř a nastav dočasný element
                const tempDiv = this.createMeasurementElement(html);
                try {
                    // Vypočítej šířku pokud není zadána
                    if (calculatedWidth === undefined) {
                        calculatedWidth = this.calculateWidth(tempDiv, MIN_WIDTH, MAX_WIDTH);
                    }
                    // Vypočítej výšku pokud není zadána
                    if (calculatedHeight === undefined) {
                        calculatedHeight = this.calculateHeight(tempDiv, calculatedWidth, MIN_HEIGHT, MAX_HEIGHT, PADDING, BUTTON_AREA_HEIGHT);
                    }
                }
                finally {
                    // Vždy odstraň dočasný element
                    document.body.removeChild(tempDiv);
                }
                return [calculatedWidth, calculatedHeight];
            }
            /* Vytvoří dočasný element pro měření textu */
            createMeasurementElement(html) {
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = html;
                tempDiv.style.cssText = `position: absolute;visibility: hidden;font-size: 14px;font-family: Arial, sans-serif;padding: 20px;box-sizing: border-box;`;
                document.body.appendChild(tempDiv);
                return tempDiv;
            }
            /* Vypočítá šířku podle obsahu s ohledem na <br> značky */
            calculateWidth(element, minWidth, maxWidth) {
                // Uložíme původní styl
                const originalWhiteSpace = element.style.whiteSpace;
                // Získáme HTML obsah elementu
                const htmlContent = element.innerHTML;
                // Rozdělíme obsah podle <br> značek
                const lines = htmlContent.split(/<br\s*\/?>/i);
                let maxLineWidth = 0;
                // Procházíme každý řádek a najdeme nejširší
                lines.forEach(line => {
                    // Vytvoříme dočasný element pro měření
                    const tempElement = document.createElement('div');
                    tempElement.style.whiteSpace = 'nowrap';
                    tempElement.style.visibility = 'hidden';
                    tempElement.style.position = 'absolute';
                    tempElement.style.top = '-9999px';
                    // Zkopírujeme relevantní styly z původního elementu
                    const computedStyle = window.getComputedStyle(element);
                    tempElement.style.font = computedStyle.font;
                    tempElement.style.fontSize = computedStyle.fontSize;
                    tempElement.style.fontFamily = computedStyle.fontFamily;
                    tempElement.style.fontWeight = computedStyle.fontWeight;
                    tempElement.style.letterSpacing = computedStyle.letterSpacing;
                    tempElement.style.padding = computedStyle.padding;
                    // Nastavíme obsah řádku (bez HTML značek kromě základního formátování)
                    tempElement.innerHTML = line.trim();
                    // Přidáme do DOM pro měření
                    document.body.appendChild(tempElement);
                    // Změříme šířku
                    const lineWidth = tempElement.offsetWidth;
                    maxLineWidth = Math.max(maxLineWidth, lineWidth);
                    // Odebereme dočasný element
                    document.body.removeChild(tempElement);
                });
                // Vrátíme původní styl
                element.style.whiteSpace = originalWhiteSpace;
                // Přidáme padding a aplikujeme min/max omezení
                return Math.max(minWidth, Math.min(maxWidth, maxLineWidth + 50));
            }
            /* Vypočítá výšku podle obsahu a šířky */
            calculateHeight(element, targetWidth, minHeight, maxHeight, padding, buttonAreaHeight) {
                element.style.cssText += `width: ${targetWidth - padding}px;white-space: normal;overflow-wrap: break-word;`;
                const textHeight = element.offsetHeight;
                return Math.max(minHeight, Math.min(maxHeight, textHeight + buttonAreaHeight));
            }
            /**
            * ErrorBox s možností navázat formou promisse
                * @param text  text chybového dialogu*
                * @param title  titulek dialogu
            */
            ErrorBox(text, title = "jres:27350270") {
                const def = $.Deferred();
                const cnt = (this._content === undefined) ? GContent.createContent() : this._content;
                cnt.dialogs.error(title, text)
                    .on("close", function (ev, o, args) {
                    def.resolve(true);
                });
                return def.promise();
            }
            //#region obsolete metody časem vyhodit
            /**
               * @deprecated Použijte místo toho metodu DatumKonceVynucene()
             */
            VynuceneDatumKonce(pamDataType, param, metoda) {
                const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                return this.DatumKonceVynucene(Content, pamDataType, param, metoda);
            }
            /**
                 * @deprecated Použijte místo toho metodu HistorieObjektu()
             */
            Historie(pamDataType, param, metoda) {
                const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                return this.HistorieObjektu(Content, pamDataType, param, metoda = 'historie');
            }
            /**
              * @deprecated Použijte místo toho metodu PracovniDoba()
            */
            PlanPracovniDoby(ip_rok_obd_mzdy, ip_ixs_ppv, frmName, layoutdescriptor = "L3M2S1") {
                const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                return this.PracovniDoba(Content, ip_rok_obd_mzdy, ip_ixs_ppv, frmName, layoutdescriptor);
            }
            /**
               * @deprecated Použijte místo toho metodu UcetniProfil()
              */
            UcetniProfilPAM(dataIn, title) {
                const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                return this.UcetniProfil(Content, dataIn, title);
            }
            /**
             * @deprecated Použijte místo toho metodu HistorieSlozek()
             */
            HistorieSlozky(typSlozky, ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy) {
                const Content = (this._content === undefined) ? GContent.createContent() : this._content;
                switch (typSlozky) {
                    case "historieTrvaleSlozky":
                        return this.HistorieSlozek(Content, "Trvale", ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy);
                        break;
                    case "historieSrazky":
                        return this.HistorieSlozek(Content, "Srazky", ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy);
                        break;
                    case "historieExekuce":
                        return this.HistorieSlozek(Content, "Exekuce", ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy);
                        break;
                    case "historieMesicniZmeny":
                        return this.HistorieSlozek(Content, "MesicniZmeny", ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy);
                        break;
                    default:
                        break;
                }
                ;
            }
            //#endregion
            /**
             * Vypočítá šířku sloupce na základě délky textu
             * @param textLength délka textu v pixelech
             * @param pixelsPerChar počet pixelů na znak
             * @param padding vnitřní odsazení
             * @param minWidth minimální šířka
             * @param maxWidth maximální šířka
             * @returns vypočítaná šířka sloupce
             */
            calculateColumnWidth(textLength, pixelsPerChar = 8, padding = 20, minWidth = 300, maxWidth = 800) {
                const calculatedWidth = textLength * pixelsPerChar + padding;
                return Math.min(Math.max(calculatedWidth, minWidth), maxWidth);
            }
            /**
             * Vypočítá výšku dialogu na základě počtu řádků
             * @param rowCount počet řádků
             * @param rowHeight výška jednoho řádku
             * @param overhead režie (prostor nad a pod řádky)
             * @param minHeight minimální výška
             * @param maxHeight maximální výška
             * @returns vypočítaná výška dialogu
             */
            calculateDialogHeight(rowCount, rowHeight = 35, overhead = 150, minHeight = 250, maxHeight = 600) {
                const calculatedHeight = rowCount * rowHeight + overhead;
                return Math.min(Math.max(calculatedHeight, minHeight), maxHeight);
            }
            /**
                * Zobrazí chyby předané jako parametr, zobrazí je v modálním okně +umožní uživateli buď pokračovat, nebo akci přerušit.
                *
                * @param chyby Pole chybových záznamů (GPamtpomDto), kde se rozlišuje závažnost (info, warning, error).
                * @param nezastavovatPriChybe Pokud je true, uživatel nebude moci přerušit akci (tlačítko "Přerušit" nebude dostupné)
                * @param optDialog Volitelné nastavení dialogu.
                * @param onSuccessResult Volitelný callback, který vrací hodnotu při úspěšném dokončení (výchozí: () => "OK").
                * @returns Promise, která se vyřeší objektem { result, error? }:
                *          - result: návratová hodnota z `onSuccessResult`
                *          - error: volitelný popis chyby
                *          - při přerušení se promise zamítne (reject) s hodnotou "DIALOG_KNT_CANCEL"
             */
            ZobrazChyby(typ, chyby, zastavovatPriChybe = true, onSuccessResult = () => "OK") {
                if (!chyby)
                    return Promise.resolve({ result: onSuccessResult() });
                if (chyby.length === 0)
                    return Promise.resolve({ result: onSuccessResult() });
                return new Promise((resolve, reject) => {
                    let prerusit = true; // indikuje, zda akci ukončit nebo pokračovat
                    // počty jednotlivých typů zpráv
                    const counts = {
                        infos: chyby.filter(x => x.int_1 === 0).length,
                        warnings: chyby.filter(x => x.int_1 === 1).length,
                        errors: chyby.filter(x => x.int_1 === 2).length
                    };
                    if (!(counts.infos || counts.warnings || counts.errors)) {
                        resolve({ result: onSuccessResult() });
                        return;
                    } // pokud nejsou žádné zprávy, pokračuj
                    // složení titulku podle počtu chyb a varování
                    const parts = [];
                    if (counts.errors > 0)
                        parts.push(`chyby:${counts.errors}`);
                    if (counts.warnings > 0)
                        parts.push(`varování:${counts.warnings}`);
                    if (counts.infos > 0)
                        parts.push(`informace:${counts.infos}`);
                    //const title = parts.length > 0 ? `Počet ${parts.join(", ")}` : "";
                    const title = parts.length > 0 ? `Počet ${parts.join(" ")}` : "";
                    let sloupce = new Gordic.Data.GridFormat();
                    // default
                    let delkaMax = 0; // maximální délka textu pro rozhodnutí o šířce okna
                    let sirka = 0; // šířka okna
                    let vyska = this.calculateDialogHeight(chyby.length); // výška okna podle počtu řádků
                    let velikost_zbytku = 0; // rezervováno pro ikonu a okraje ...
                    switch (typ) {
                        // Zobrazení s ikonou a třemi textovými poli spojenými do jednoho
                        case Pam.TypyZobrazeniChyb.ikona_char_123:
                            // maximální délka textu pro rozhodnutí o šířce okna
                            delkaMax = Pam.MaxConcatenatedLength(chyby, ["char_1", "char_2", "char_3"]);
                            sirka = this.calculateColumnWidth(delkaMax); // vyčíslení šířky okna podle délky textu
                            velikost_zbytku = 60; // rezervováno pro ikonu a okraje
                            sloupce = new Gordic.Pam.Columns().SestavSloupce([
                                { coltype: Gordic.Pam.PamColumnType.icon_vysledek_kontroly, colTemplate: { name: "int_1" } },
                                {
                                    coltype: Gordic.Pam.PamColumnType.text, colTemplate: {
                                        name: 'text', customClass: 'left', caption: 'Text', width: sirka,
                                        cellTemplate: (metarow) => `${metarow.char_1 ?? ""} ${metarow.char_2 ?? ""} ${metarow.char_3 ?? ""}`.trim()
                                    }
                                }
                            ]);
                            break;
                        // Zobrazení s ikonou, oblastí a třemi textovými poli spojenými do jednoho
                        case Pam.TypyZobrazeniChyb.ikona_oblast_text:
                            delkaMax = Pam.MaxConcatenatedLength(chyby, ["char_2"]);
                            sirka = this.calculateColumnWidth(delkaMax); // vyčíslení šířky okna podle délky textu
                            velikost_zbytku = 270; // rezerevováno pro ikonu oblast a okraje
                            //sirka = 750; // šířka okna je konstantní
                            sloupce = new Gordic.Pam.Columns().SestavSloupce([
                                { coltype: Gordic.Pam.PamColumnType.icon_vysledek_kontroly, colTemplate: { name: "int_1" } }, // int_1 => závažnost
                                { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "char_1", caption: "Oblast" } }, // char_1 => oblast
                                { coltype: Gordic.Pam.PamColumnType.text, colTemplate: { name: 'char_2', customClass: 'left', caption: 'Text', width: sirka } } // char_2 => text chyby
                            ]);
                            break;
                    }
                    // Sestavení formuláře s gridem zobrazujícím chyby
                    const form = new Gordic.Forms.Form({ layoutDescriptor: "L-0-12-0, M-0-12-0, S-0-12-0" })
                        .addSection()
                        .addField("ggrid", {
                        data: chyby,
                        renderMode: "auto",
                        columnMode: "full", // "full" "fit"
                        navigationMode: "row",
                        showTopPanel: false,
                        showHeaderRow: true,
                        showBottomPanel: false,
                        columns: sloupce
                    });
                    const commandBar = [
                        ...(counts.errors === 0 || !zastavovatPriChybe ? [{
                                primary: true,
                                action: new GAction({
                                    name: "actOk", caption: "Pokračovat", icon: "gi-tick",
                                    run: (ev) => { prerusit = false; $.content(ev.currentTarget).close(); }
                                })
                            }] : []),
                        {
                            action: new GAction({
                                name: "actCancel", caption: "Přerušit", // Tlačítko "Přerušit" – vždy dostupné                            
                                run: (ev) => { prerusit = true; $.content(ev.currentTarget).close(); }
                            })
                        }
                    ];
                    const Content = this._content ?? GContent.createContent();
                    // Zobrazení modálního okna a obsluha zavření
                    Pam.Forms.prototype.WindowFromFrmModal(form, { title, commandBar, width: sirka + velikost_zbytku, height: vyska }, Content).on("close", () => {
                        prerusit
                            ? reject(Pam.Forms.DIALOG_KNT_CANCEL) // uživatel akci přerušil
                            : resolve({ result: onSuccessResult() }); // úspěch
                    });
                });
            }
            /**
             * Sesbírá data z formuláře do objektu
             * @param form formulář (JQuery objekt)
             * @returns objekt s nasbíranými daty
             */
            static CollectData(form) {
                const data = {};
                form.findFields().gfield("model", "collect", data);
                return data;
            }
            /**
             * Validuje formulář
             * @param form formulář (JQuery objekt)
             * @returns true pokud je formulář validní, jinak false
             */
            static ValidateForm(form) {
                form.findFields().gfield("validate");
                return form.gform("isValid", true);
            }
        }
        Forms.DIALOG_KNT_CANCEL = "DIALOG_KNT_CANCEL"; // konstantní hodnota pro zrušení dialogu v případě chyb z KNT (viz. ZobrazChyby)
        Pam.Forms = Forms;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
