var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        class Reports {
            constructor(content) {
                this._content = content;
            }
            /**
            * konverze sestavaInfo do IPamReportObject pro GFRM
            * @param sestavaInfo
            * @param customDto  - uživatelská data, která se přenesou do X0001 a X0002
            * @returns
            **/
            static sestavaInfo2ReportObjectGFRM(sestavaInfo, customDto = null) {
                const res = {
                    platnost: "199801",
                    nazev: sestavaInfo.nazev_sestavy || "??",
                    id_ses: sestavaInfo.id_ses || "",
                    ixs_alv: sestavaInfo.ixs_alv || "",
                    ixs_alf: sestavaInfo.ixs_frm || "",
                    ixs_str: sestavaInfo.ixs_str || "",
                    outputStyle: 'PDF',
                    customDto: customDto || null, // Přenese do X0001 a X0002
                    serverParameterMethod: "Gordic.Pam.Client.GTisky:ParametrySestavyGFRM"
                };
                return res;
            }
            /**
             * Nalezení hodnoty položky  v GFRM dat struktuře
             * @param regions      pole regionů
             * @param regionName   název regionu
             * @param itemName       položka regionu
             * @returns [string]     textová hodnota
             */
            static findGfrItem(regions, regionName, itemName) {
                const region = regions.find(region => region.region_name?.toUpperCase() === regionName.toUpperCase());
                if (region?.items) {
                    const item = region.items.find(item => item.item_name?.toUpperCase() === itemName.toUpperCase());
                    return item?.hodnota || ""; // Vrátí hodnotu nebo prázdný řetězec
                }
                return ""; // Jistící návěští pokud se nic nenajde
            }
            /**
            * Nalezení položky v GFRM dat struktuře a transformace na date
            * @param regions      pole regionů
            * @param regionName   název regionu
            * @param itemName       položka regionu
            * @returns [string]     textová hodnota
            */
            static getGfrItemDate(regions, regionName, itemName) {
                let dateStr = this.findGfrItem(regions, regionName, itemName); // načtení položky
                if (dateStr === "")
                    return null; // pokud je prázdná, dám tam null
                return parseDate(dateStr);
            }
            /**
             * Konverze dat z GRFM formuláře do GFrmDataRegionDto[]
             * @param data dat z gfrm formuláře
             * @returns GFrmDataRegionDto[] objekt
             */
            static GFrmData2Regions(data) {
                return Object.keys(data).map(region_name => {
                    const regionData = data[region_name][0] || {};
                    return {
                        region_name,
                        items: Object.keys(regionData).map(item_name => ({
                            item_name,
                            hodnota: regionData[item_name],
                        })),
                    };
                });
            }
            /**
             * Linearizace dat z GFRM fomuláře do jednoduché struktury
             * @param regions pole regionů GFrmDataRegionDto
             * @returns
             */
            static LinerarizeGFrmData(gfrmData) {
                const result = [];
                if (!gfrmData || typeof gfrmData !== 'object') {
                    return result;
                }
                const regions = Pam.Reports.GFrmData2Regions(gfrmData);
                if (!Array.isArray(regions)) {
                    return result;
                }
                regions.forEach(region => {
                    const regionName = region?.region_name || '';
                    if (Array.isArray(region?.items)) {
                        region.items.forEach(item => {
                            result.push({
                                region_name: Pam.toString(regionName),
                                item_name: Pam.toString(item?.item_name || ''),
                                hodnota: Pam.toString(item?.hodnota || '')
                            });
                        });
                    }
                });
                return result;
            }
            /**
         * Transformace dat formuláře do struktury GFrmDataDto
         * @param reportObject objekt sestavy
         * @param data dat z gfrm formuláře
         * @returns GFrmDataDto objekt
         */
            static GFrmData2Dto(reportObject, data) {
                const regions = Object.keys(data).map(region_name => {
                    const regionData = data[region_name][0] || {};
                    return {
                        region_name,
                        items: Object.keys(regionData).map(item_name => ({
                            item_name,
                            hodnota: regionData[item_name],
                        })),
                    };
                });
                return { ixs_gfr: "", ixs_alv: reportObject.ixs_alv, id_ses: reportObject.id_ses, regions };
            }
            /**
            * Vytvoření sestavy na pozadí
            * @param parentContent Rodičovská content
            * @param parmReportObj parametry pro reporter
            */
            GenerujSestavuNaPozadi(parmReportObj) {
                const reportParams = {
                    reportId: `${parmReportObj.ixs_str}/${parmReportObj.ixs_alv}/${parmReportObj.ixs_alf}/0`,
                    platnost: parmReportObj.platnost,
                    serverParameterMethod: parmReportObj.serverParameterMethod,
                    outputStyle: parmReportObj.outputStyle,
                    customDto: parmReportObj.customDto
                };
                const genCnt = this._content.createServiceContent([Gordic.Report.WebClient.GReportAsyncGenerator, {}]);
                return new Promise((resolve, reject) => {
                    genCnt.readyAwait
                        .then(() => { return genCnt.generate(reportParams); }) //Samotne generovani
                        .then((res) => {
                        const doc = new Gordic.Report.WebClient.GReportDocument(this._content);
                        return doc.downloadDocument(Gordic.Report.WebClient.GReportTreeControlTS.getDownloaderParams(res));
                    })
                        .then(() => {
                        resolve();
                    })
                        .catch((error) => {
                        reject(error);
                    });
                });
            }
            /**
             * Vytvoření sestavy na pozadí a uložení do ELE
             * @param parmReportObj Parametry pro reporter
             * @param ixs Identifikátor pro tabulku wflsesx
             * @param guidProgress GUID pro sledování stavu - nezahajuji ani jej  nekončím, to ponechávám na nadřazené metodě
             */
            GenerujSestavuDoELE(parmReportObj, ixs, guidProgress = null) {
                const cancellationToken = new GObservableObject({ cancelled: false });
                const cancelAct = new GAction({
                    name: "repGenCancelAct", caption: "jres:27350318", // Storno
                    run: () => {
                        cancellationToken.update({ cancelled: true });
                        cancelAct.update({ caption: "jres:27350319", enabled: false }); //RC 27350319 : Stornuji
                    }
                });
                const repParams = {
                    reportId: `${parmReportObj.ixs_str}/${parmReportObj.ixs_alv}/${parmReportObj.ixs_alf}/0`,
                    platnost: parmReportObj.platnost,
                    serverParameterMethod: parmReportObj.serverParameterMethod,
                    outputStyle: parmReportObj.outputStyle,
                    customDto: parmReportObj.customDto
                };
                const genCnt = this._content.createServiceContent([Gordic.Report.WebClient.GReportAsyncGenerator, {}]);
                genCnt.on("progress", (progress) => {
                    this._content.progressOperation({
                        text: Gordic.Report.WebClient.GReportTreeControlTS.formatProgressMessage(progress.text),
                        progress: progress.current,
                        total: progress.total,
                        cancelAction: cancelAct
                    });
                });
                if (guidProgress) {
                    this._content.progressOperation({ id: guidProgress, text: "jres:27350320", cancelAction: cancelAct }); //RC 27350320 : Generování PDF dokumentu
                }
                return new Promise((resolve, reject) => {
                    genCnt.readyAwait
                        .then(() => genCnt.generate(repParams, cancellationToken))
                        .then((res) => {
                        if (res.fileInfo) {
                            const elefileDto = {
                                ixs: ixs,
                                typ_elp: 20, // Příloha
                                s_sgn: 0 // Nepodepsaný
                            };
                            if (guidProgress) {
                                this._content.progressOperation({ id: guidProgress, text: "jres:27350321", cancelAction: cancelAct }); //RC 27350321 : Ukládání do elektronického úložiště
                            }
                            Pam.ELEupload(this._content, elefileDto, res.fileInfo, true)
                                .then((eleInfo) => {
                                if (guidProgress) {
                                    this._content.progressOperation({ id: guidProgress, text: "jres:27350322", cancelAction: cancelAct }); //RC 27350322 : Uloženo v pořádku
                                }
                                resolve(eleInfo);
                            })
                                .catch(reject);
                        }
                        else {
                            reject();
                        }
                    })
                        .catch((err) => {
                        reject(err);
                    });
                });
            }
            /**
             * Zobrazení GFRM sestavy - vytáhne ji z databáze a nastaví požadované menu
             * @param parmReportObj IPamReportObject například PAMKCH01_setting_ESU
             * @param customDto GPamtpomDto přenese do X0001 a X0002
             */
            GFrmShow(parmReportObj, customDto) {
                const repParams = {
                    reportId: `${parmReportObj.ixs_str}/${parmReportObj.ixs_alv}/${parmReportObj.ixs_alf}/0`,
                    platnost: parmReportObj.platnost,
                    serverParameterMethod: parmReportObj.serverParameterMethod,
                    customDto: customDto
                };
                const guid = Pam.CreateGuid();
                this._content.beginOperation({ id: guid, text: 'Generuji' });
                const genCnt = this._content.createServiceContent([Gordic.Report.WebClient.GReportAsyncGenerator, {}]);
                // Obalení do standardního Promise
                return new Promise((resolve, reject) => {
                    genCnt.readyAwait
                        .then(() => genCnt.generate(repParams))
                        .then((res) => {
                        const options = {
                            Form: res.fileInfo.guid,
                            genRes: res,
                            generatorOptions: {
                                parentContent: this._content
                            },
                            params: repParams
                        };
                        const gfrm = this._content.navigate(Gordic.Report.WebClient.GFrmControl, options) //Zobrazeni okna s GFRM sestavou
                            .on("close", () => { genCnt.clear(res).then(() => { genCnt.close(); }); }); //Po zavření okna je nutné provést úklid                        
                        resolve($.content(gfrm));
                    })
                        .then((result) => {
                        this._content.endOperation(guid);
                        return result;
                    })
                        .catch((error) => {
                        const title = "Chyba při generování sestavy";
                        console.error(title);
                        console.error(Pam.dumpObj(error));
                        new Pam.Forms(genCnt).ExceptionWindow(error.exception, title, 27350047);
                        this._content.endOperation(guid);
                        reject(error);
                    });
                });
            }
        }
        /*
         * Nastavení tisků PAMKCH01 za osoby
         */
        Reports.PAMKCH01_setting_ESU = {
            id_ses: "PAMKCH01",
            nazev: "Výpis kontrolního chodu - PAMKCH01",
            ixs_alv: "0000ALV013N5",
            ixs_alf: "GZNOALF0A1M3",
            ixs_str: "0000STR00808",
            platnost: "199801",
            serverParameterMethod: "Gordic.Pam.Client.GTisky:ParametrySestavyALL"
        };
        /* ESPPIM02 - Výsluhové nároky za ESU */
        Reports.ESPPIM02_esu = {
            platnost: "199801",
            nazev: "Výsluhové nároky",
            id_ses: "ESPPIM02",
            ixs_alv: "GZNOALV0C4EG",
            ixs_alf: "GZNOALF0CZTS",
            ixs_str: "0000STR00V0R",
            serverParameterMethod: "Gordic.Pam.Client.GTisky:ParametrySestavyESU"
        };
        /* ESPPRA01 - Záznam o sociálním pojištění */
        Reports.ESPPRA01_gfrm = {
            platnost: "199801",
            nazev: "Záznam o sociálním pojištění",
            id_ses: "ESPPRA01",
            ixs_alv: "GZNOALV0BZ0Q",
            ixs_alf: "GZNOALF0CUFP",
            ixs_str: "0000STR00V0R",
            serverParameterMethod: "Gordic.Pam.Client.GTisky:ParametrySestavyGFRM"
        };
        /*
        * požadavek na kurz
        */
        Reports.PPPSKO01_setting_ESU = {
            id_ses: "PPPSKO01",
            nazev: "Žádost o účast na otevřeném kurzu",
            ixs_alv: "GZNOALV0CVYF",
            ixs_alf: "GZNOALF0EK3L",
            ixs_str: "0000STR00V8N",
            platnost: "199801",
            serverParameterMethod: "Gordic.Pam.Client.GTisky:ParametrySestavyGFRM",
            outputStyle: 'PDF'
        };
        Pam.Reports = Reports;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
