var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        class Kontroly {
            /**
             * Konstruktor nastaví content a rok ob mzdy
             * @param content   content
             * @param rok_obd_mzdy kontrolované období
    
             */
            constructor(content, rok_obd_mzdy) {
                this._content = content;
                this._rok_obd_mzdy = rok_obd_mzdy;
            }
            /**
             * Vykonání vybrané množiny kontrolních chodů
             * @param ixs_kch identifikace KCH
             * @param skupina za kterou se tvoří KCH. Pokud se jedná o osoby je nutné mít tyto vložené v db
             */
            RunKCH(ixs_kch, skupina) {
                let Content = this._content;
                let def = $.Deferred();
                const className = "Gordic.Pam.Server.GKontrolniChodyAsync";
                const guid = Pam.CreateGuid();
                Content.beginOperation({ id: guid, text: "Vykonávám kontrolní chody" });
                let err_txt = "";
                let vysledekKCH = {};
                Gordic.Async.GTaskManager.getInitPromise().always(() => {
                    Gordic.Async.GTaskManager.on(`change.${guid}`, className, function (ctx, args) {
                        if (ctx.progress != null) {
                            Content.progressOperation({ id: guid, text: ctx.progress.text, progress: ctx.progress.current });
                        }
                    });
                    Gordic.Async.GTaskManager.on(`done.${guid}`, className, function (ctx, args) {
                        vysledekKCH = ctx.result || {};
                        let spgresult = vysledekKCH.transaction_result || null;
                        if (spgresult != null && !Pam.CheckSpgOk(spgresult)) { // pokud došlo k chybě 
                            err_txt = (spgresult.op_err_txt || "").trim() + " [" + spgresult.op_err_code + "]";
                            Gordic.Pam.LogujSpgChybu(spgresult);
                        }
                    });
                    Gordic.Async.GTaskManager.on(`fail.${guid}`, className, function (ctx, args) {
                        err_txt = "Chyba při vykonávání KCH" + Pam.dump(args);
                        GDlg.showException(args.exception);
                        //console.error("AsyncTask fail  ", this, args);
                    });
                    Gordic.Async.GTaskManager.on(`always.${guid}`, className, function (ctx, args) {
                        let task = this;
                        let zobrazitSestavu = false;
                        Content.progressOperation({ id: guid, text: "Zjišťování nalezených chyb", cancelAction: undefined });
                        let zavaznostVysledku = (vysledekKCH && vysledekKCH.data && vysledekKCH.data.length > 0) ? vysledekKCH.data[0].int_1 : 999 /* Pam.Interface.GKChZavaznost.OK */;
                        switch (zavaznostVysledku) {
                            case 999 /* Pam.Interface.GKChZavaznost.OK */: break;
                            case 0 /* Pam.Interface.GKChZavaznost.Informace */:
                            case 1 /* Pam.Interface.GKChZavaznost.Varovani */:
                            case 2 /* Pam.Interface.GKChZavaznost.Chyba */:
                                zobrazitSestavu = true;
                            default: // sem to neleze                        
                                break;
                        }
                        Content.endOperation(guid);
                        Gordic.Async.GTaskManager.off("." + guid); // zastavím TASK
                        task.clean();
                        if (zobrazitSestavu) {
                            Content.beginOperation({ id: guid, text: "zobrazuji sestavu", cancelAction: undefined });
                            new Gordic.Pam.Reports(Content).GenerujSestavuNaPozadi(Pam.Reports.PAMKCH01_setting_ESU)
                                .then(function () {
                                Content.endOperation(guid);
                            });
                        }
                        else {
                            Content.dialogs.messageBox("jres:27850133", //RC 27850133 : Výsledek kontroly
                            "jres:27850134", //RC 27850134 : Nenalezeny žádné chyby.
                            [GDlg.mbbOk], GDlg.mbiInfo);
                        }
                    });
                    let dto = {
                        command: "KONTROLNI_CHOD", data: [{
                                int_1: this._rok_obd_mzdy,
                                int_2: skupina,
                                char_1: ixs_kch,
                                char_2: "", // ixs_any pro osoby nepodstatné
                                char_3: "" // název pracoviště nebo AAJ .. pro osoby nepodstatné
                            }]
                    };
                    let cancelAct = new GAction({
                        name: "cancelAct",
                        caption: "jres:27850131", //RC 27850131 : Přerušit kontrolu
                        run: () => { err_txt = "jres:27850132"; } //RC 27850132 : Kontrola přerušena!
                    });
                    Pam.startAsync(Content, className, dto, guid, "jres:27850135", 0, 100, cancelAct); //RC 27850135 : Spuštění kontroly
                });
                return def.promise(); // vracím čekačku
            }
        }
        Pam.Kontroly = Kontroly;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
