//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        016_Gordic.Pam.Validators              </Name>
//    <Description> Validátory PAM </Description>
//    <Author>      Zdeněk Molík                         </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2018     </Copyright>
//    <Created>     2018-07-30                            </Created>
//  </FileHeader>
var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        class Validators {
            /*
             *  Získání vlastnosti ixs_ppv
             * */
            static Ziskej_ixs_ppv(lokace, data) {
                if (data === undefined)
                    throw new GError(27350038, lokace + " " + "jres:zadán prázdný objekt pro zjištění identifikace PPV");
                let ixs_ppv = data["ixs_ppv"] || "";
                if (ixs_ppv === "")
                    throw new GError(27350039, lokace + " " + "jres:27350230"); //RC 27350230 : neobsahuje ixs_ppv
                return ixs_ppv;
            }
            /*
             *  Získání vlastnosti rok_obd_mzdy
            * */
            static Ziskej_rok_obd_mzdy(lokace, data) {
                if (data === undefined)
                    throw new GError(27350040, lokace + " " + "jres:zadán prázdný objekt pro zjištění identifikace PPV");
                let rok_obd_mzdy = data["rok_obd_mzdy"] || 0;
                if (rok_obd_mzdy === 0)
                    throw new GError(27350041, lokace + " " + "jres:27350231"); //RC 27350231 : neobsahuje rok_obd_mzdy
                return rok_obd_mzdy;
            }
            /*
             *  const validator_mesic = [
                    new Gordic.Validators.Required(),
                    new Gordic.Validators.Range({ min: 1, max: 12, message: "Měsíc musí být v rozsahu 1..12" }),
                    new Gordic.Validators.Base({
                    validate: function (value, field) {
                        if (value === null) return false;
                        if (value % 1 != 0) return false; // test na celé číslo
                        let isValid = value._validatationState === "verified" || typeof value._validatationState === "undefined";
                        if (!isValid) {
                            this.message = value._validatationMsg;
                            this.errorType = "error";
                            this.stopping = true;
                        }
                        return isValid;
                    }
                }), new Gordic.Validators.Required()];
                */
            /**
             * Validace hodnoty - všeobecný string ID
             * @author TVitek
             * @date 01.01.2022
             */
            static ppp_id_str(id_length) {
                return [
                    new Gordic.Validators.Required(),
                    new Gordic.Validators.Length({ max: id_length }),
                    new Gordic.Validators.RegExp({ pattern: "[A-Z_]", message: "Neplatný identifikátor, povolené znaky: A-Z_" })
                ];
            }
            /**
             * Validace hodnoty - datumu (rozsahu a intervalu)
             * @author TVitek
             * @date 31.05.2024
             * @param date_min Hodnota minimálního datumu
             * @param date_max Hodnota maximálního datumu
             * @param field_mode Příznak jestli je pole začátek (od) nebo konec (do)
             * @param field_dependency Název pole které je v intervalové vazbě
             */
            static Datum(date_min, date_max, field_mode = undefined, field_dependency = undefined) {
                return new Gordic.Validators.Base({
                    validate: function (value, source) {
                        let min = (date_min == "default") ? new Date(1900, 0, 1, 0, 0, 0, 0) : date_min;
                        let max = (date_max == "default") ? new Date(2999, 11, 31, 23, 59, 59, 999) : date_max;
                        let v1 = value ?? new Date(value.getFullYear(), value.getMonth(), value.getDate(), 0, 0, 0, 0);
                        if (v1 != null && (v1 < min || v1 > max)) {
                            this.message = "Datum je mimo rozsah";
                            return false;
                        }
                        let value2 = (field_dependency != null ? $(source).closest(".gform").findFields(field_dependency).gfield("getValue") : undefined);
                        let v2 = value2 ?? new Date(value2.getFullYear(), value2.getMonth(), value2.getDate(), 0, 0, 0, 0);
                        if (field_mode == "end" && v1 != null && v2 != null && v1 < v2) {
                            this.message = "Kolize intervalu";
                            return false;
                        }
                        return true;
                    },
                    message: "",
                    stopping: true,
                    errorType: "error"
                });
            }
            /*
             Nastaví prázdný seznam validátorů pro dané pole
             */
            static clear(fields) {
                fields.forEach(field => field.gfield("option", "validators", []));
            }
        }
        Validators.__static_ctor = (() => { })();
        /**
        * Validace hodnoty roku
        * - povinnost
        * - rozsah 1900–2050
        */
        Validators.rok = [
            new Gordic.Validators.Required(),
            new Gordic.Validators.Range({ min: 1900, max: 2050, message: "Rok musí být v rozsahu 1900 až 2050" })
        ];
        /**
         * Validace hodnoty - telefonu
         * @author TVitek
         * @date 01.01.2022
         */
        Validators.Telefon = new Gordic.Validators.Base({
            validate: function (value, field) {
                if (value === null || value.trim() === '')
                    return true;
                var re = /^\d{6,20}$|^\d{3}\x20{1}\d{3}\x20{1}\d{3}$|^(\+{1}\d{1,10}|\+{1}\d{1,10}\x20{1}|\d{1,11}\x20{1})(\d{3}\x20{1}\d{3}\x20{1}\d{3}|\d{9})$/;
                return (re.test(String(value).toLowerCase()));
            },
            message: "Neplatné telefonní číslo",
            stopping: true
        });
        /**
         * Validace hodnoty - emailu
         * @author TVitek
         * @date 01.01.2022
         */
        Validators.Email = new Gordic.Validators.Base({
            validate: function (value, field) {
                if (value === null)
                    return true;
                var re = /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
                return (re.test(String(value).toLowerCase())) || (value == 3) || (value == 4);
            },
            message: "Neplatná emailová adresa",
            stopping: true
        });
        /**
         * Validace hodnoty - HH:MM
         * @author zmolik
         * @date 09.08.2024
         */
        Validators.HHMM = new Gordic.Validators.Base({
            validate: function (value, field) {
                if (value === null || value.trim() === '')
                    return true;
                const re = /^(?:[01]\d|2[0-3]):[0-5]\d$/;
                return (re.test(Gordic.Pam.formatHHMMtxt(value))); // otestuji si na normalizovaný tvar
            },
            message: "Hodiny a minuty musí být ve formátu HH:MM",
            stopping: true
        });
        Pam.Validators = Validators;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
