/**
 * Startup pro PAM
 * Inicializuje globální úložiště PAM_CACHE hodnotami z GInitPamDto.
 *
 * @author ZMOLIK
 */
var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        /**
         * Společná inicializace modulů PAM - prvotní nastavení PAM_CACHE.
         * Pokud PAM_CACHE ještě neexistuje, vytvoří se nová instance.
         * Do PAM_CACHE se uloží hodnoty z předaného DTO.
         *
         * @param dto Data pro inicializaci typu GInitPamDto
         */
        function Init(dto) {
            // Kontrola existence globálního úložiště PAM_CACHE, případně jeho vytvoření
            if (!window.PAM_CACHE) {
                window.PAM_CACHE = new Gordic.Pam.Cache(); // Vytvoření jediné instance PAM_CACHE
            }
            // Uložení hodnot z DTO do PAM_CACHE, pokud nejsou definovány, nastaví se na null
            const cache = window.PAM_CACHE;
            cache.set("licAdr", dto.licAdr ?? null);
            cache.set("rokobdlogin", dto.rokobdlogin ?? null);
            cache.set("ixs_vaj", dto.ixs_vaj ?? null);
            cache.set("typInst", dto.typInst ?? null);
        }
        Pam.Init = Init;
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
