/**
* Vynucené datum konce - obecný objekt
 * @param pamDataType datový objekt PAMu
 * @param param   parametry, které budou předány ISL mětodě, typicky se jedná o SXS
 * @param metoda  název metody, pokud není uvedena použije se 'datumKonce'
 */
Gordic.Pam.Forms.prototype.DatumKonceVynucene = function (cnt, pamDataType, param, metoda = 'datumKonce') {
    const Content = cnt; // parent content
    const def = $.Deferred();
    let sloupce = [];
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.date, colTemplate: { name: "datum_do", caption: "jres:27350161", } }); //RC 27350161 : Vynucené datum konce
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.dat_zmena, colTemplate: { name: "dat_zmena" } });
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.text, colTemplate: {
            name: "zdroj_zmeny_txt", width: 100, fixedWidth: true, caption: "jres:27350147", //RC 27350147 : Zdroj změny
            cellTemplate: (dataRow) => {
                if (dataRow.ixp && dataRow.ixp !== "")
                    return "Doklad " + dataRow.ixp;
                let text = "";
                switch (dataRow.zdroj_zmeny) {
                    case 1:
                        text = "Ruční zadání";
                        break;
                    case 2:
                        text = "Doklad z rozhraní " + (dataRow.ixp) ? dataRow.ixp : "";
                        break;
                    case 3:
                        text = "Automatické replikace";
                        break;
                    default:
                        text = "Neurčeno";
                        break;
                }
                return text;
            }
        }
    });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.nazev_rf, colTemplate: { name: "nazev_rf" } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.poznamka254, colTemplate: { name: "poznamka" } });
    let opt = { name: "vynuceneDatumFRM", layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" };
    let optDialog = {
        //menuBar: menu,
        width: window.innerWidth - 50,
        height: window.innerHeight - 50,
        title: "jres:27350161" //RC 27350161 : Vynucené datum konce
    };
    Gordic.Pam.Isl(Content, pamDataType.IslObject, metoda, param)
        .done(function (result) {
        let data = result;
        if (data.length === 0) {
            let title = "jres:27350161"; //RC 27350161 : Vynucené datum konce
            let text = "jres:27350162"; //RC 27350162 : Nejsou evidovány nebo přístupné žádné údaje o vynuceném datu konce.
            Content.dialogs.messageBox(title, text, [GDlg.mbbOk], GDlg.mbiInfo);
            def.resolve();
        }
        else {
            let frm = new Gordic.Forms.Form(opt)
                .addField("ggrid", {
                customClass: "datumKonceGrid",
                data: data,
                renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                columnMode: "fit", // fit, full
                navigationMode: "row", // row, cell
                rowNumbers: true,
                searchColumns: ["poznamka", "nazev_rf"], // nejde vyhledávání podle počítaného sloupce - zdroj_zmeny_txt
                columns: new Gordic.Pam.Columns().SestavSloupce(sloupce),
                gridOptions: {
                    showHeaderRow: true,
                },
            });
            Gordic.Pam.Forms.prototype.WindowFromFrm(frm, optDialog, Content);
            //let form = $("<div>").prop("doRemoveOnClose", true).gform("createFrom", frm);
            //Content.dialogs.showWindow(form, null, optDialog)
            def.resolve();
        }
    })
        .fail(function (result) {
        let text = "jres:27350163"; //RC 27350163 : Nepodařilo se sestavit zobrazení datumů konce
        new Gordic.Pam.Forms().ErrorBox(text);
        //Content.dialogs.error("Chyba", text);
        console.error(pamDataType.IslObject, metoda, param);
        def.reject(text);
    });
    return def.promise();
};
