var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        var WebControls;
        (function (WebControls) {
            var Forms;
            (function (Forms) {
                const { gcontent } = Decorators;
                let DokumentySYM = class DokumentySYM extends Gordic.GContentBase {
                    /**
                     * Vytvoří formulář pro dokumenty systemizovaného místa
                     *
                     * @author  ZMOLIK
                     * @date  22.02.2024
                     *
                     * @param cnt parent content
                     * @param ixs_sym identifikace SYM
                     * @param {?{name: string},?{layoutDescriptor: string}, } options Parametry formuláře.
                     * @returns
                     */
                    static createForm(cnt, ixs_sym, options) {
                        const Content = cnt; // parent content            
                        const def = $.Deferred();
                        const GRID_CUSTOM_CLASS = 'grid_' + Pam.CreateGuid();
                        const ISL_SEZNAM_PRILOH = Gordic.Isl.PersCenterSystemizace.listAttachment(rq => { return { filters: { ixs_sym: ixs_sym } }; });
                        const COLUMNS = new Gordic.Pam.Columns(Content).SestavSloupce([
                            { coltype: Gordic.Pam.PamColumnType.text100, colTemplate: { name: "filename", caption: "jres:27350283", align: "left" } }, //RC 27350283 : Soubor
                            { coltype: Gordic.Pam.PamColumnType.text254, colTemplate: { name: "popis", caption: "jres:27350284", align: "left" } }, //RC 27350284 : Popis
                            { coltype: Gordic.Pam.PamColumnType.icon_pripona, colTemplate: { name: "soubor_pri" } },
                            { coltype: Gordic.Pam.PamColumnType.filesizetxt, colTemplate: { name: "velikost", caption: "jres:27350285", width: 80 } }, //RC 27350285 : Velikost
                            { coltype: Gordic.Pam.PamColumnType.nazev_rf, colTemplate: { name: "nazev_rf" } },
                            { coltype: Gordic.Pam.PamColumnType.dat_zmena, colTemplate: { name: "dat_zmena" } },
                        ]);
                        const optionsInternal = {
                            name: options && options.name ? options.name : "dokumentySymFrm",
                            layoutDescriptor: options && options.layoutDescriptor ? options.layoutDescriptor : "L1M1S2 LMS-1-11-0"
                        };
                        ISL_SEZNAM_PRILOH
                            .getData()
                            .then((seznamDokumentu) => {
                            const formBuilder = new Gordic.Forms.Form({ name: optionsInternal.name, layoutDescriptor: optionsInternal.layoutDescriptor })
                                .addSection({ layoutDescriptor: "LMS-0-12-0" })
                                .addField("ggrid", {
                                data: seznamDokumentu,
                                customClass: GRID_CUSTOM_CLASS,
                                renderMode: "paged-sync", // auto, all-at-once, paged-sync, paged-async
                                columnMode: "fit", // fit, full
                                navigationMode: "row", // row, cell
                                columns: COLUMNS,
                                rowNumbers: true,
                                showTopPanel: true,
                                showHeaderRow: true,
                                showBottomPanel: true
                            });
                            def.resolve({
                                form: formBuilder,
                                grid_customclass: GRID_CUSTOM_CLASS
                            });
                        });
                        return def.promise();
                    }
                };
                DokumentySYM = __decorate([
                    gcontent
                ], DokumentySYM);
                Forms.DokumentySYM = DokumentySYM;
            })(Forms = WebControls.Forms || (WebControls.Forms = {}));
        })(WebControls = Pam.WebControls || (Pam.WebControls = {}));
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
