/**
* Historie - obecný objekt
* @param {GContent} cnt Content, do kterého se bude vkládat dialog
* @param {Gordic.Pam.IPamDataType} pamDataType Datový objekt PAMu
* @param {any} param Parametry, které budou předány ISL metodě, typicky se jedná o SXS
* @param {string} metoda Název metody, pokud není uvedena, použije se 'historie'
*/
Gordic.Pam.Forms.prototype.HistorieObjektu = function (cnt, pamDataType, param, metoda = 'historie') {
    const Content = cnt; // parent content
    const jeServisRezimPam = Content["pam_servis_wk"] > 0;
    const def = $.Deferred();
    const sloupce = [];
    //sloupce.push({ coltype: Gordic.Pam.PamColumnType.datetime, colTemplate: { name: "dat_zmena", caption: "Změněno" } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.dat_zmena_ms, colTemplate: { name: "dat_zmena", caption: "Změněno" } });
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.text,
        colTemplate: {
            width: 100, fixedWidth: true,
            name: "typ_zmeny_txt",
            caption: "jres:27350145", //RC 27350145 : Typ změny
            hidden: true, // sloupec neukazuji
            cellTemplate: (dataRow) => {
                let text = "";
                switch (dataRow.typ_zmeny) {
                    case 1:
                        text = "Vytvoření";
                        break;
                    case 2:
                        text = "Editace";
                        break;
                    case 3:
                        text = "Změna intervalu";
                        break;
                    case 4:
                        text = "Změna aktivity";
                        break;
                    case 5:
                        text = "Fyzické odstranění";
                        break;
                }
                if (text === "") { // pokud nebyl rozpoznám typ_zmeny, zkusím to podle typu záznamu ( toto nastává jenom pokud se nezískává z gindhis, ale pomocé fce)
                    switch (dataRow.typ_zazn) {
                        case "I":
                            text = "vytvoření";
                            break;
                        case "U":
                            text = "editace";
                            break;
                        default:
                            "???";
                    }
                }
                return text;
            }
        }
    });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.text254, colTemplate: { name: "zmena_txt", caption: "jres:27350146" } }); //RC 27350146 : Změna
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.text100, colTemplate: {
            name: "zdroj_zmeny_txt",
            hidden: true, // sloupec neukazuji
            caption: "jres:27350147", //RC 27350147 : Zdroj změny
            cellTemplate: (dataRow) => {
                if (dataRow.ixp && dataRow.ixp !== "")
                    return "Doklad " + dataRow.ixp;
                let text = "";
                switch (dataRow.zdroj_zmeny) {
                    case 1:
                        text = "Ruční zadání";
                        break;
                    case 2:
                        text = "Doklad z rozhraní " + (dataRow.ixp) ? dataRow.ixp : "";
                        break;
                    case 3:
                        text = "Automatické replikace";
                        break;
                    default:
                        text = "Neurčeno";
                        break;
                }
                return text;
            }
        }
    });
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.text, colTemplate: {
            hidden: true, // sloupec neukazuji
            name: "zkr_ag",
            caption: "jres:27350139", //RC 27350139 : Agenda
            width: 40, fixedWidth: true
        }
    });
    //sloupce.push({ coltype: Gordic.Pam.PamColumnType.text12, colTemplate: { name: "ixp", caption: "jres:27350141" } });//RC 27350141 : Doklad
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.poznamka254, colTemplate: {
            hidden: true, // sloupec neukazuji
            name: "poznamka"
        }
    });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "skryta", hidden: true } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.nazev_rf, colTemplate: { name: "nazev_rf" } });
    // pokud je servisní režim PAM, tak nastavím sloupce, které jsou skryté v gridu, aby se zobrazily
    if (jeServisRezimPam) {
        const skryteSloupce = new Set(["typ_zmeny_txt", "zdroj_zmeny_txt", "zkr_ag", "poznamka"]);
        // Nastaví hidden: false pro všechny sloupce, kde skryta == 1
        sloupce.forEach(x => {
            if (x.colTemplate?.name && skryteSloupce.has(x.colTemplate.name)) {
                if (x.colTemplate)
                    x.colTemplate.hidden = false;
            }
        });
    }
    Gordic.Pam.Isl(Content, pamDataType.IslObject, metoda, param)
        .done(function (result) {
        const data = result;
        if (data.length === 0) {
            Content.dialogs.messageBox((pamDataType.HistoryTitle) ? pamDataType.HistoryTitle : "Historie", "Nejsou evidovány nebo přístupné žádné údaje v historii požadovaného záznamu.", [GDlg.mbbOk], GDlg.mbiInfo);
            def.resolve();
        }
        else {
            const opt = { name: "historieFRM", layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" };
            const frm = new Gordic.Forms.Form(opt);
            const form = $.newDiv().prop("doRemoveOnClose", true).gform("createFrom", frm);
            form
                .appendTo(form)
                .gformsection("create", "")
                .ggrid({
                customClass: "historieGrid",
                data: data,
                renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                columnMode: "fit", // fit, full
                navigationMode: "row", // row, cell
                rowNumbers: true,
                scrollHelperTemplate: (row) => {
                    return Gordic.Templates.Formatters.datetime(row.dat_zmena);
                },
                searchColumns: ["zmena_txt", "poznamka", "nazev_rf"], // nejde vyhledávání podle počítaného sloupce - typ_zmeny_txt, zdroj_zmeny_txt
                columns: new Gordic.Pam.Columns().SestavSloupce(sloupce),
                showHeaderRow: true,
                defaultProfile: {
                    condFormats: [{ formula: "EQUALS(@skryta,1)", bg: Gordic.Components.Grid.CondFormats.CondFormatBg.gray }] // skrytý řádek si označím šedě
                }
            })
                .gautofit();
            const optDialog = {
                //menuBar: menu,
                //TODO rozumně dopočítávat, podle velikosti dat
                width: window.innerWidth - 350,
                height: window.innerHeight - 50,
                title: (pamDataType.HistoryTitle) ? pamDataType.HistoryTitle : "Historie",
            };
            Content.dialogs.showWindow(form, null, optDialog);
            def.resolve();
        }
    })
        .fail(function (result) {
        const text = "Nepodařilo se sestavit historii";
        Content.dialogs.error("Chyba", text);
        console.error(pamDataType.IslObject, metoda, param);
        def.reject(text);
    });
    return def.promise();
};
