/**
* Historie individuálního kalendáře
* @param {string} ip_ixs_ppv  identifikace PPV
* @param {number} ip_rok_obd_mzdy období mzdy
*/
Gordic.Pam.Forms.prototype.HistorieIndKalendare = function (cnt, ip_ixs_ppv, ip_rok_obd_mzdy) {
    const Content = cnt; // parent content
    const def = $.Deferred();
    let nazev = "Historie individuálního kalendáře";
    const sloupce = [
        { coltype: Gordic.Pam.PamColumnType.pid, colTemplate: { name: "ixs_kal", caption: "PID kalendáře" } },
        {
            coltype: Gordic.Pam.PamColumnType.mes_rok_txt, colTemplate: {
                name: "rok_obd_zad",
                caption: "Z období",
            }
        },
        { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "nazev", caption: "Název" } },
        { coltype: Gordic.Pam.PamColumnType.nazev_rf, colTemplate: { name: "pamvika_zmenu_prov_txt" } },
        { coltype: Gordic.Pam.PamColumnType.dat_zmena, colTemplate: { name: "pamvika_dat_zmena", caption: "Datum změny" } },
        { coltype: Gordic.Pam.PamColumnType.poznamka50, colTemplate: { name: "poznamka", caption: "Poznámka" } },
    ];
    const opt = { name: "historieIndKalendare", layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" };
    const optDialog = {
        width: window.innerWidth - 50,
        height: window.innerHeight - 50,
        title: nazev
    };
    //natáhnu seznam historie trvalé složky
    cnt.isl.PamKalendar.historieIndKalendare({ ixs_ppv: ip_ixs_ppv, rok_obd_mzdy: ip_rok_obd_mzdy })
        .getData()
        .done((data) => {
        const frm = new Gordic.Forms.Form(opt)
            .addField("ggrid", {
            data: data,
            renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
            columnMode: "fit", // fit, full
            navigationMode: "row", // row, cell
            rowNumbers: true,
            scrollHelperTemplate: "{pamvika_dat_zmena}",
            columns: new Gordic.Pam.Columns().SestavSloupce(sloupce),
        });
        const form = $("<div>").prop("doRemoveOnClose", true).gform("createFrom", frm);
        Content.dialogs.showWindow(form, null, optDialog);
        def.resolve();
    })
        .fail(function (result) {
        const text = "Nepodařilo se sestavit historii individuálního kalendáře";
        Content.dialogs.error("Chyba", text);
        def.reject(text);
    });
    return def.promise();
};
