/**
  * Historie složek - okno se seznamem vypočtených složek reprezentujících historii vyplácení trvalých složek, srážek a exekucí v průběhu času
  * @param {string} typSlozky typ složky - fragment, který se poosílá do ISL
  * @param {string} ip_ixs_ppv  identifikace PPV
  * @param {number} ip_por_cislo pořadové číslo trvalé složky
  * @param {number} ip_rok_obd_mzdy období mzdy
*/
Gordic.Pam.Forms.prototype.HistorieSlozek = function (cnt, typSlozky, ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy) {
    const Content = cnt; // parent content
    const def = $.Deferred();
    let nazev = "";
    switch (typSlozky) {
        case "Trvale":
            nazev = "Historie zadané složky";
            break;
        case "Srazky":
            nazev = "Historie srážky";
            break;
        case "Exekuce":
            nazev = "Historie exekuce";
            break;
        case "MesicniZmeny":
            nazev = "Historie měsíční změny";
            break;
        default:
            break;
    }
    ;
    const sloupce = [
        { coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "slozka_mzdy", caption: "Složka", width: 80 } },
        { coltype: Gordic.Pam.PamColumnType.text100, colTemplate: { name: "slozka_mzdy_nazev", caption: "Název složky", customClass: "left " } },
        { coltype: Gordic.Pam.PamColumnType.c, colTemplate: { name: "c_mena", caption: "Částka", width: 80 } },
        { coltype: Gordic.Pam.PamColumnType.text, colTemplate: { name: "mena_zkr", width: 60, fixedWidth: true, customClass: "center", caption: "Měna" } },
        { coltype: Gordic.Pam.PamColumnType.dat_od, colTemplate: { name: "dat_od" } },
        { coltype: Gordic.Pam.PamColumnType.dat_do, colTemplate: { name: "dat_do" } },
        { coltype: Gordic.Pam.PamColumnType.mes_rok_txt, colTemplate: { name: "rok_obd_zad", caption: "Z období" } },
        { coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "poc_dni", caption: "Dní", width: 70 } },
        { coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "poc_hodin", caption: "Hodin", width: 70 } },
        { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "druh_nazev", caption: "Druh" } },
        { coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "id_sr", caption: "Id" } },
        { coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "km_sr", caption: "Km" } },
        { coltype: Gordic.Pam.PamColumnType.text12, colTemplate: { name: "ixs_esu", caption: "Příjemce" } }
    ];
    // už není potřeba, lze využít export do XLSX na gridu
    //const ExportXLSAct = new GAction({
    //    name: "ExportToXLS",
    //    tooltip: "jres:27350148", //RC 27350148 : Export seznamu do Excelu ve formátu XLS
    //    caption: "XLS",
    //    icon: Gordic.Pam.Icons.inprogress,
    //    favorite: true,
    //    align: "normal",
    //    run: function (ev, _obj) {
    //        const grid = $.content(ev.currentTarget).find(".ggrid")
    //        const columns = grid.ggrid("trueColumns");
    //        const dataGridu = grid.ggrid("getView").getDataRows(true);
    //
    //        const filename = "Historie složky_" + Gordic.Templates.Formatters.datetime(new Date(), "yyyyddMMhhmmss");
    //
    //        //const strategy = new Gordic.Data.Exports.GCsvStrategy({ includeHeaderRow: true, delimiter: ";" });
    //        const strategy = new Gordic.Data.Exports.GXlsxStrategy({ includeHeaderRow: true });
    //        const opts: Gordic.Data.Exports.IGDataExpoterOpts = { sourceElement: grid };
    //        const exportData = Gordic.Data.Exports.prepareExportInput(columns, dataGridu);
    //
    //        new Gordic.Data.Exports.GDataExporter(strategy, opts).downloadFile(exportData, filename);
    //    }
    //});
    //const menu: MenuParams[] = [
    //    {
    //        align: "opposite",
    //        favorite: true,
    //        action: ExportXLSAct
    //    }];
    const opt = { name: "historieSlozkyFRM", layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" };
    const optDialog = {
        //menuBar: menu,
        width: window.innerWidth - 50,
        height: window.innerHeight - 50,
        title: nazev
    };
    const l_filtr = {
        ixs_ppv: ip_ixs_ppv, poradi_puv: ip_por_cislo, rok_obd_mzdy: ip_rok_obd_mzdy
    };
    //natáhnu seznam historie trvalé složky
    Gordic.Isl.PamPpvVypoctenaSlozka.list({ filters: l_filtr })
        .getView({ fragments: ["*", typSlozky] })
        .done((view) => {
        const pocet = view.getCount();
        if (pocet === 0) {
            Content.dialogs.messageBox("Historie - informace", "Nejsou evidovány nebo přístupné žádné údaje v historii vybrané složky.", [GDlg.mbbOk], GDlg.mbiInfo);
            def.resolve();
        }
        else {
            const data = view.getDataRows();
            const dataVcetneProcesoru = new Gordic.Data.View(data || [], {
                processors: {
                    rok_obd_zad_txt: new Gordic.Data.ComputedFieldsProcessor((rows) => {
                        for (let i = 0, ii = rows.length; i < ii; i++) {
                            rows[i].data.rok_obd_zad_txt = Gordic.Pam.RokObdMzdy2TXT(rows[i].data.rok_obd_zad);
                        }
                    }),
                }
            });
            const frm = new Gordic.Forms.Form(opt)
                .addField("ggrid", {
                customClass: "historieSlozkyGrid",
                data: dataVcetneProcesoru,
                renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                columnMode: "fit", // fit, full
                navigationMode: "row", // row, cell
                rowNumbers: true,
                scrollHelperTemplate: "{dat_zmena} - {popis_akce}",
                searchColumns: ["popis_akce"],
                columns: new Gordic.Pam.Columns().SestavSloupce(sloupce),
            });
            const form = $("<div>").prop("doRemoveOnClose", true).gform("createFrom", frm);
            Content.dialogs.showWindow(form, null, optDialog);
            def.resolve();
        }
    })
        .fail(function (result) {
        const text = "Nepodařilo se sestavit historii složky";
        Content.dialogs.error("Chyba", text);
        console.error(typSlozky, ip_ixs_ppv, ip_por_cislo, ip_rok_obd_mzdy);
        def.reject(text);
    });
    return def.promise();
};
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        Gordic.Pam.WebControls.PamPoznamky.ts                       </Name>
//    <Description> Uživatelské poznámky pro PAM                                </Description>
//    <Author>      Radim Dušek                                                 </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2025                            </Copyright>
//    <Created>     2025-09-17                                                  </Created>
//  </FileHeader>
var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        var WebControls;
        (function (WebControls) {
            /** Poznámky PAM.
             * Editaci řídí patrametr GIN - Režim editace uživatelských poznámek (gin_rez_pozn)
             */
            class PamPoznamky {
                constructor(options) {
                    this.poznamkyCount = new GObservableObject({ value: "0" });
                    this.sxs = (options.sxs ?? "").toString();
                    this.typ_obj = options.typ_obj;
                    this.cnt = options.cnt;
                    this.idPanelu = options.idPanelu ?? "panelPoznamky";
                    this.nazevPanelu = options.nazevPanelu ?? "jres:27850418"; //RC 27850418 : Poznámky
                    this.gnotePanel = new Gordic.GNotePanel();
                }
                createPoznamky() {
                    this.panel.empty();
                    if (Gordic.Prefabs.Utils.isEmpty(this.sxs) || Gordic.Prefabs.Utils.isEmpty(this.typ_obj)) {
                        const text = $("<div>").text("jres:27850416"); //RC 27850416 : Některý z identifikátorů poznámky není naplněn.
                        this.cnt.dialogs.alert("jres:27850417", text); //RC 27850417 : Upozornění
                    }
                    else {
                        this.gnotePanel.create(this.panel, null, {
                            sxs: this.sxs,
                            typObj: this.typ_obj,
                            showTiskovaField: true,
                            count: (count) => {
                                this.poznamkyCount.value = String(count);
                                this.poznamkyCount.update();
                            }
                        }, true // hideColorBtn
                        );
                    }
                }
                getSidePanel() {
                    return {
                        leaf: {
                        //caption: this.nazevPanelu, 
                        //badge: this.poznamkyCount
                        },
                        icon: "fa-sticky-note-o",
                        id: this.idPanelu,
                        caption: this.nazevPanelu,
                        side: "right",
                        open: (ev, obj) => {
                            this.panel = $(ev.target);
                            this.createPoznamky();
                        }
                    };
                }
            }
            WebControls.PamPoznamky = PamPoznamky;
        })(WebControls = Pam.WebControls || (Pam.WebControls = {}));
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        Gordic.Pam.Forms.PlanPracovniDoby.ts           </Name>
//    <Description>   Formulář s plánem pracovní doby                    </Description>
//    <Author>      ZMOLIK                                               </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2024                     </Copyright>
//    <Created>     2024-01-11                                           </Created>
//  </FileHeader>
/**
 * Formulář s plánem pracovní doby
 * @param cnt: parent content
 * @param ip_rok_obd_mzdy období mzdy
 * @param ip_ixs_ppv  identifikace PPV
 * @param frmName    název formuláře
 * @param layoutdescriptor layoutdescriptor [L3M2S1]
 */
Gordic.Pam.Forms.prototype.PracovniDoba = function (cnt, ip_rok_obd_mzdy, ip_ixs_ppv, frmName, layoutdescriptor = "L3M2S1") {
    const Content = cnt; // parent content
    const def = $.Deferred();
    Gordic.Isl.PamPpv.listRozpisPracovniDoby(rq => { return { filters: { ixs_ppv: ip_ixs_ppv, rok_obd_mzdy: ip_rok_obd_mzdy } }; }).getData()
        .done(function (result) {
        // nápočet počtu hodin a směn
        let pocetHodin = 0.0;
        let pocetSmen = 0;
        for (var i = 0; i < result.length; i++) {
            pocetHodin = pocetHodin + Gordic.Pam.toNumber(result[i].hod_den_prepocteno);
            if (result[i].priz_prac === 100)
                pocetSmen++; // 100 = pracovní den
        }
        cnt.isl.PamPpv.ixs_kal_ind({ ixs_ppv: ip_ixs_ppv, rok_obd_mzdy: ip_rok_obd_mzdy }).get().done(function (ind_kal) {
            const jeIndKal = !!ind_kal; // převede na bool
            const outFRM = new Gordic.Forms.Form({ name: frmName, layoutDescriptor: layoutdescriptor });
            if (layoutdescriptor == "L5M5S1") {
                outFRM
                    .addSection({
                    name: "sekce1",
                    //label: "sekce1",
                    layoutDescriptor: "L5M5S1 L-4-4-2 M-4-4-2 S-4-4-2"
                })
                    .addRow({ label: "jres:27850361" }) //RC 27850361 : Plán hodin
                    .addField("gnumberbox", {
                    name: "plan_hodiny",
                    initialValue: pocetHodin,
                    decimals: 4,
                    disabled: true,
                })
                    .addSection({
                    name: "sekce2",
                    //label: "sekce2",
                    layoutDescriptor: "L5M5S1 L-4-4-2 M-4-4-2 S-4-4-2"
                })
                    .addRow({ label: "jres:27850362" }) //RC 27850362 : Plán směn
                    .addField("gnumberbox", {
                    name: "plan_smeny",
                    decimals: 4,
                    initialValue: pocetSmen,
                    disabled: true
                })
                    .addSection({
                    name: "sekce3",
                    //label: "sekce3",
                    layoutDescriptor: "L5M5S1 L-2-10-0 M-2-10-0 S-2-10-0"
                })
                    .addField("gcheck", {
                    name: "ind_kal",
                    initialValue: jeIndKal,
                    label: "jres:27850363", //RC 27850363 : Individuální kalendář
                    disabled: true
                })
                    .addSection({
                    name: "sekce4",
                    //label: "sekce4",
                    layoutDescriptor: "L5M5S1"
                });
                if (jeIndKal) {
                    outFRM.addRow({ label: "jres:27850364" }) //RC 27850364 : PID kalendáře
                        .addField("gstringbox", Gordic.Prefabs.String.ixs(true), {
                        name: "ixs_kal_ind",
                        model: "ixs_kal_ind",
                        initialValue: ind_kal,
                        disabled: true,
                        validators: [new Gordic.Validators.Required()],
                    });
                }
                outFRM.addSection({
                    name: "sekce5",
                    //label: "sekce5",
                    layoutDescriptor: "L6M6S1 L-0-12-0 M-0-12-0 S-0-12-0",
                    customClass: "w-L-12 w-M-12 w-S-12" // šířka sekce, dá se pomocí toho roztáhnout sekci na celou šířku i pro vícesloupcový layout
                });
            }
            else if (layoutdescriptor == "L2M2S1") {
                outFRM.addSection({
                    name: "sekce1",
                    //label: "sekce1",
                    layoutDescriptor: "L2M2S1 L-4-8-0 M-4-8-0 S-4-8-0",
                    customClass: "w-L-3 w-M-3 w-S-3"
                })
                    .addRow({ label: "jres:27850361" }) //RC 27850361 : Plán hodin
                    .addField("gnumberbox", "w-5", {
                    name: "plan_hodiny",
                    initialValue: pocetHodin,
                    decimals: 4,
                    disabled: true,
                })
                    .addRow({ label: "jres:27850362" }) //RC 27850362 : Plán směn
                    .addField("gnumberbox", "w-5", {
                    name: "plan_smeny",
                    decimals: 4,
                    initialValue: pocetSmen,
                    disabled: true
                })
                    .addField("gcheck", {
                    name: "ind_kal",
                    initialValue: jeIndKal,
                    label: "jres:27850363", //RC 27850363 : Individuální kalendář
                    disabled: true
                });
                if (jeIndKal) {
                    outFRM.addRow({ label: "jres:27850364" }) //RC 27850364 : PID kalendáře
                        .addField("gstringbox", Gordic.Prefabs.String.ixs(true), {
                        name: "ixs_kal_ind",
                        model: "ixs_kal_ind",
                        initialValue: ind_kal,
                        disabled: true,
                        validators: [new Gordic.Validators.Required()],
                    });
                }
                outFRM.addSection({
                    name: "sekce2",
                    //label: "sekce2",
                    layoutDescriptor: "L2M2S1 L-0-12-0 M-0-12-0 S-0-12-0",
                    customClass: "w-L-9 w-M-9 w-S-9"
                });
            }
            else {
                const popis = "<b class='g-state-text '> &nbsp;&nbsp;Naplánováno hodin: " + pocetHodin + "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Počet směn: " + pocetSmen + "</b>";
                outFRM.addRow(popis);
            }
            outFRM.addField("ggrid", "", {
                data: result,
                renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                columnMode: "fit", // fit, full
                navigationMode: "row", // row, cell
                showTopPanel: false,
                showHeaderRow: true,
                showBottomPanel: true,
                key: "ixs_ppv,por_cislo",
                rowsClass: function (dataRow) {
                    let row = dataRow.data;
                    if (row.priz_svatek === 100) {
                        return Gordic.Pam.Styles.pracovni_doba_svatek;
                    }
                    if (row.priz_prac !== 100) {
                        return Gordic.Pam.Styles.pracovni_doba_pracovni_den;
                    }
                    else
                        return "  ";
                },
                columns: new Gordic.Data.GridFormat()
                    .addDateColumn({ name: "datum", caption: "Datum", width: 80, fixedWidth: true })
                    .addTextColumn({ width: 100, fixedWidth: true, customClass: "center", name: "den_txt", caption: "Den" })
                    .addNumberColumn({ width: 60, fixedWidth: true, customClass: "center", name: "hod_den_prepocteno", caption: "Hodin", format: "number(N2)" })
                    .addTextColumn({ width: 100, fixedWidth: true, customClass: "center", name: "smena_od_txt", caption: "Směna od" })
                    .addTextColumn({ width: 100, fixedWidth: true, customClass: "center", name: "smena_do_txt", caption: "Směna do" })
                    .addTextColumn({ width: 100, fixedWidth: true, customClass: "center", name: "smena2_od_txt", caption: "Směna 2 od" })
                    .addTextColumn({ width: 100, fixedWidth: true, customClass: "center", name: "smena2_do_txt", caption: "Směna 2 do" })
                    .addTextColumn({ width: 80, fixedWidth: true, customClass: "center", name: "priz_prac_txt", caption: "Pracovní" })
                    .addTextColumn({ width: 80, fixedWidth: true, customClass: "center", name: "priz_svatek_txt", caption: "Svátek" })
            });
            def.resolve(outFRM);
        })
            .fail(function () {
            def.reject(null);
        });
    })
        .fail(function () {
        def.reject(null);
    });
    return def.promise();
};
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        Gordic.Pam.Forms.UcetniProfil.ts           </Name>
//    <Description>   Formulář s účetním profile                    </Description>
//    <Author>      ZMOLIK                                               </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2024                     </Copyright>
//    <Created>     2024-01-11                                           </Created>
//  </FileHeader>
Gordic.Pam.Forms.prototype.UcetniProfil = function (cnt, dataIn, title = "Účetní věta") {
    const Content = cnt; // parent content
    const typ_inst = PAM_CACHE.typInst;
    let povolenaC = // povolená částka
     [
        15 /* Gordic.Pam.Interface.PamUzaverkaUrovenUcetniVety.pamvusl_10 */,
        17 /* Gordic.Pam.Interface.PamUzaverkaUrovenUcetniVety.pamvusl_40 */,
        12 /* Gordic.Pam.Interface.PamUzaverkaUrovenUcetniVety.pamvusl_50 */
    ];
    let sloupce = [];
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.text, colTemplate: { name: "uroven_txt", caption: "Úroveň", width: 200, fixedWidth: true, sortable: false, } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.dat_od, colTemplate: { name: "dat_od_platnost_cvup", sortable: false, cellTemplate: (meta) => { return (meta.dat_od_platnost_cvup) ? Gordic.Templates.Formatters.date(meta.dat_od_platnost_cvup) : ""; } } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.dat_do, colTemplate: { name: "dat_do_platnost_cvup", sortable: false, cellTemplate: (meta) => { return (meta.dat_do_platnost_cvup) ? Gordic.Templates.Formatters.date(meta.dat_do_platnost_cvup) : ""; } } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.procento, colTemplate: { name: "pomer", sortable: false, cellTemplate: (meta) => { return (meta.pomer) ? Gordic.Templates.Formatters.number(meta.pomer * 100, "D") : ""; } } });
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.c, colTemplate: {
            name: "c", sortable: false,
            editor: {
                widget: "gnumberbox", options: [Gordic.Prefabs.Number.currency() /*, {name: "baseValue", enterToConfirm: true }*/],
            },
            customClass: (metarow, column, rowIndex, columnIndex) => {
                let data = metarow.data;
                let zakazPole = !Gordic.Pam.arrContain(povolenaC, data.uroven);
                //if (zakazPole) column.disabled = true;
                return (!Gordic.Pam.arrContain(povolenaC, data.uroven)) ? " ui-disabled " : "";
            },
        }
    });
    let nskEditor = {
        gridEvents: {
            ggridcelleditorstart: function (ev, obj) {
                // $(obj.cellInfo.cellDOM).toggleClass("g-state-background", false).toggleClass("g-state-error", false);
            }
        },
        widget: "gselectbox",
        options: $.extend(Gordic.Prefabs.Select.ekosnks(), {
            itemTemplate: "{nks:trim:encode}",
            strict: false,
            model: "model.ico=value.ico,model.nks=value.nks",
            invalidTransform: function (s) { return { nks: s }; }
        })
    };
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.nks, colTemplate: {
            name: "nks", sortable: false,
            cellTemplate: function (row) { return (row.nks) ? row.nks : ""; },
            editor: nskEditor
            /*
            editor: {
                widget: "gselectbox",
            options: $.extend(Gordic.Prefabs.Select.ekosnks(), {

                    itemTemplate: "{nks:trim:encode}",
                    strict: false,
                    model: "model.ico=value.ico,model.nks=value.nks",
                    invalidTransform: function (s) {return { nks: s };}
                })
            }
            */
        }
    });
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.text, colTemplate: {
            name: "zapocitavat_sp_txt",
            caption: "SP",
            width: 100,
            fixedWidth: true,
            sortable: false,
            cellTemplate: (meta) => { switch (meta.zapocitavat_sp) {
                case 0: return "Ano";
                case 1: return "Ne";
                default: return "";
            } },
            editor: { widget: "gselectbox", options: $.extend(Gordic.Prefabs.Select.gincpan(), { itemTemplate: "{priz_an_txt:trim:encode}", dropdown: true, strict: false }) }
        }
    });
    sloupce.push({
        coltype: Gordic.Pam.PamColumnType.text,
        colTemplate: {
            name: "zapocitavat_zp_txt", caption: "ZP", width: 100, fixedWidth: true, sortable: false,
            cellTemplate: (meta) => { switch (meta.zapocitavat_zp) {
                case 0: return "Ano";
                case 1: return "Ne";
                default: return "";
            } },
            editor: { widget: "gselectbox", options: $.extend(Gordic.Prefabs.Select.gincpan(), { itemTemplate: "{priz_an_txt:trim:encode}", dropdown: true, strict: false }) }
        }
    });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.text16, colTemplate: { name: "typ_upr" } });
    sloupce.push({ coltype: Gordic.Pam.PamColumnType.cfu_set, colTemplate: { name: "ucetni_veta" } }); // nad CFU nefunguje vypnutí pomocí sortable?
    let grid = $("<div>");
    let buttonPanel = $('<div>').appendTo(grid).gbuttonpanel();
    const menuParams = [];
    let AkceNahled1020 = new GAction({
        name: "AkceNahled1020", icon: Gordic.Pam.Icons.aktualizovat, caption: "Rezervační kontace",
        tooltip: "Zobrazí náhled na první řádek rezervační kontace",
        run: function () {
            Gordic.Isl.PamUzaverka.nahled1020(dataIn).getData().done((data) => {
                let gridNahled1020 = $("<div>");
                let sloupceNahled1020 = [];
                sloupceNahled1020.push({ coltype: Gordic.Pam.PamColumnType.cfu_set, colTemplate: { name: "ucetni_veta", sortable: false } });
                let ucetniVetaGrid = $("<div id='kontace_1020nahled'>").appendTo(gridNahled1020)
                    .ggrid({
                    data: [data],
                    rowsEnabled: false,
                    rowsClass: Gordic.Pam.Styles.ucetni_profil_readonly,
                    renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                    columnMode: "fit", // fit, full
                    navigationMode: "row", // row, cell
                    rowNumbers: true,
                    columns: new Gordic.Pam.Columns(Content).SestavSloupce(sloupceNahled1020)
                });
                Content.dialogs.showModalWindow(ucetniVetaGrid, null, {
                    width: window.innerWidth - 50,
                    height: window.innerHeight - 50,
                    title: "Náhled na první řádek rezervační kontace"
                });
            });
        }
    });
    // pro úroveň účetní věty měsíční změna, trvalá složka(společně se srážkou) a na MO se zaplne volba pro získání náhledu účetní větu rezervačního zápisu
    if ((dataIn.uroven == 16 /* Gordic.Pam.Interface.PamUzaverkaUrovenUcetniVety.pamsmzm */ || dataIn.uroven == 14 /* Gordic.Pam.Interface.PamUzaverkaUrovenUcetniVety.pamdslo */)
        &&
            (typ_inst === 10) // a pouze  pro MO
    ) {
        menuParams.push({ action: AkceNahled1020, favorite: true, align: "opposite" });
    }
    buttonPanel.gbuttonpanel({ params: menuParams });
    Gordic.Isl.PamUzaverka.ziskejUcetniVetu({ rq: dataIn }).getData().done((data) => {
        let ucetniVetaGrid = $("<div id='ucetni_veta'>").appendTo(grid)
            .gautofit()
            .ggrid({
            data: data,
            rowsEnabled: (dataRow) => { return (dataRow.editable); },
            rowsClass: (metarow) => { return (!metarow.data.editable) ? Gordic.Pam.Styles.ucetni_profil_readonly : ""; },
            renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
            columnMode: "fit", // fit, full
            navigationMode: "row", // row, cell
            rowNumbers: true,
            columns: new Gordic.Pam.Columns(Content).SestavSloupce(sloupce)
        })
            .ggridroweditor({
            beforeStart: function (ev, info) {
                //let col = Pam.nullSafeStr(info, 'cellInfo', 'column');
                let data = info.cellInfo.data;
                let col = info.cellInfo.column;
                let name = (col || "")["name"] || "";
                // podle úrovně zakáži její editaci
                switch (name) {
                    case "c":
                        if (!Gordic.Pam.arrContain(povolenaC, data.uroven))
                            ev.preventDefault();
                        break;
                }
            },
            save: function (ev, info) {
                //let data: Gordic.Pam.Interface.GUcetniVetaPAMDto = info.cellInfo.data; // tady jsou data původní
                let data = ev; // je to divné, ale data z řádku jsou zde
                let rqSave = { data: data };
                Gordic.Isl.PamUzaverka.ulozUcetniVetu(rqSave).getData()
                    .done((data) => {
                    // refresh? asi není potřeba
                    //console.log("Data: "+ data);
                });
            }
        });
        let optDialog = {
            width: window.innerWidth - 50,
            height: window.innerHeight - 50,
            title: title
        };
        Content.dialogs.showModalWindow(grid, null, optDialog);
    }); // typ inst
};
