var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        var Seznam;
        (function (Seznam) {
            /**
            * Šablona pro zobrazení gridu se seznamem adres osoby
            */
            class Adresy extends Gordic.Pam.SeznamBase {
                /**
                 * Konstruktor
                 * @param {GContent} parentContent Parent content
                 * @param {IPamSeznamBaseOptions} userSetting Uživatelské nastavení, které přepíše / doplní implicitní nastavení
                 */
                constructor(parentContent, userSetting) {
                    const Content = parentContent;
                    const editFrm = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1" });
                    editFrm
                        .addSection()
                        .addRow({ label: "jres:27850360", required: true }) //RC 27850360 : PID adresy
                        .addField("gstringbox", Gordic.Prefabs.String.ixs(true), {
                        name: "ixs_ado",
                        model: "ixs_ado",
                        disabled: true,
                        validators: [new Gordic.Validators.Required()],
                    })
                        .addRow({ label: "jres:27850059", required: true }) //RC 27850059 : Typ adresy
                        .addField("gselectbox", Gordic.Pam.Prefabs.TypAdresy(Content), {
                        dropdown: true,
                        name: "typ_ado",
                        model: "model.typ_ado=value.typ_ado,model.typ_ado_txt=value.typ_ado_txt",
                        validators: [new Gordic.Validators.Required()]
                    })
                        .addRow({ label: "jres:27350060", required: true }) //RC 27350060 : Platnost
                        .addField("gdatebox", "w-6", {
                        name: "dat_od",
                        model: "dat_od",
                        initialValue: Pam.RokObdMzdy2FirstDay(PAM_CACHE.rokobdlogin), // výchozí hodnota - první den z rok_obd_mzdy
                        valueType: "date",
                        validators: [
                            new Gordic.Validators.Required(),
                            new Gordic.Validators.Base({
                                message: "jres:27850321", //RC 27850321 : Pole Platnost od musí být menší nebo rovno poli Platnost do
                                validate: (value, source) => {
                                    // při nezadání hodnoty zabere validátor Required
                                    if (value === null)
                                        return true;
                                    // hodnota z pole
                                    const datOd = value;
                                    // hodnota z pole Platnost do, pokud je null, pak 31.12.2999
                                    const datDo = $(source).closest(".gform").findFields("dat_do").gfield("getValue") ?? Pam.RokObdMzdy2LastDay(35999);
                                    return datOd <= datDo;
                                }
                            }),
                        ]
                    })
                        .addField("gdatebox", "w-6", {
                        name: "dat_do",
                        model: "dat_do",
                        valueType: "date",
                        initialValue: Pam.RokObdMzdy2LastDay(35999), // výchozí hodnota poslední den z 35999, tzn. 31.12.2999
                        formatter: (value, editMode) => { if (!value)
                            return ""; return value.getFullYear() === 2999 ? "" : Gordic.Templates.Formatters.date(value); }, // skrývání 2999
                        validators: [
                            new Gordic.Validators.Required(),
                            new Gordic.Validators.Base({
                                message: "jres:27850323", //RC 27850323 : Pole Platnost do musí být větší nebo rovno poli Platnost od
                                validate: (value, source) => {
                                    // při nezadání hodnoty zabere validátor Required
                                    if (value === null)
                                        return true;
                                    // hodnota z pole Platnost od
                                    const datOd = $(source).closest(".gform").findFields("dat_od").gfield("getValue");
                                    // hodnota z pole, pokud je null, pak 31.12.2999
                                    const datDo = Pam.toDate(value) ?? Pam.RokObdMzdy2LastDay(35999);
                                    return datDo >= datOd;
                                }
                            }),
                        ]
                    })
                        .addRow({ label: "jres:27850053" }) //RC 27850053 : Ulice
                        .addField("gstringbox", {
                        name: "ulice",
                        model: "ulice",
                        //modelValueTransform: {
                        //    apply: (modelValue) => modelValue?.trim(),
                        //},
                    })
                        .addRow({ label: "jres:27850060" }) //RC 27850060 : Č. or., Č. pop.
                        .addField("gstringbox", "w-6", {
                        name: "cor",
                        model: "cor",
                        modelValueTransform: {
                            apply: (modelValue) => modelValue?.trim(),
                        },
                    })
                        .addField("gstringbox", "w-6", {
                        name: "cpop",
                        model: "cpop",
                        modelValueTransform: {
                            apply: (modelValue) => modelValue?.trim(),
                        },
                    })
                        .addRow({ label: "jres:27850051" }) //RC 27850051 : Obec
                        .addField("gstringbox", {
                        name: "obec",
                        model: "obec",
                        modelValueTransform: {
                            apply: (modelValue) => modelValue?.trim(),
                        },
                    })
                        .addRow({ label: "jres:27850052" }) //RC 27850052 : Část obce
                        .addField("gstringbox", {
                        name: "cast_obce",
                        model: "cast_obce",
                        modelValueTransform: {
                            apply: (modelValue) => modelValue?.trim(),
                        },
                    })
                        .addRow({ label: "jres:27850056" }) //RC 27850056 : PSČ
                        .addField("gselectbox", Gordic.Prefabs.Select.ginspsc(), {
                        name: "psc",
                        model: "model.stat=value.stat,model.psc=value.psc",
                        serverFilters: {
                            aktivita: 100,
                        }
                    })
                        .addRow({ label: "jres:27850058" }) //RC 27850058 : Stát
                        .addField("gselectbox", Gordic.Prefabs.Select.gincsta(), {
                        name: "stat",
                        model: "model.stat=value.stat",
                        serverFilters: {
                            aktivita: 100,
                        },
                    })
                        .addRow({ label: "jres:27350062" }) //RC 27350062 : Poznámka
                        .addField("gstringbox", {
                        name: "poznamka",
                        model: "poznamka",
                        modelValueTransform: {
                            apply: (modelValue) => modelValue?.trim(),
                        },
                    })
                        .addRow({ label: "jres:27850050" }) //RC 27850050 : Datum změny
                        .addField("gdatebox", "w-6", {
                        name: "dat_zmena",
                        model: "dat_zmena",
                        disabled: true,
                        valueType: "datetime"
                    });
                    /**
                     * Callback na transformaci sesbíraného DTO
                    * @param {Gordic.Pam.SeznamBase} seznam objekt, odkud lze získat původní řádek
                    * @param {Object} dataFormulare data ze zadávacího formuláře
                    * @param {Object} serverData data zaslaná ze serveru (tímto způsobem lze dodat konstanty mimo formuláře)
                    * @param {string} cmd příkaz, který se vykonává INSERT, UPDATE ...
                    * @returns {Object} objekt s transformovanými daty
                    */
                    const _transformDTOcallback = function (seznam, dataFormulare, serverData, cmd) {
                        const result = dataFormulare;
                        const radek = seznam.SelectedRow; // z vybraného řádku
                        // není součástí formuláře
                        result.ixs_esu = serverData["ixs_esu"];
                        // ixs_ado z vybraného řádku
                        if (radek != null) {
                            result.ixs_ado = radek.ixs_ado;
                        }
                        ;
                        // transformace pro jednotlivé typy akcí
                        switch (cmd) {
                            case "INSERT":
                                result.poznamka = Pam.NVL(result.poznamka, Pam.sestavPoznamku("Vytvořeno"));
                                result.aktivita = 100;
                                break;
                            case "UPDATE":
                                result.aktivita = 100;
                                break;
                            case "DELETE":
                                result.aktivita = 900;
                                break;
                            case "KONTROLA":
                                break;
                        }
                        return result;
                    };
                    /**
                    * Callback po vytvoření formuláře
                    * @param {Gordic.Pam.SeznamBase} _seznam SeznamBase
                    * @param {GContent} _cnt content
                    * @param {GForm} frm formulář
                    * @param {IPamSeznamBaseCommand} cmd, příkaz, který se vykonává INSERT, UPDATE ...
                    * @param {any} data získaná pomocí waitForValues
                    * @returns objekt s transformovanými daty
                    */
                    const _onOpenFrm = function (_seznam, _cnt, frm, cmd, data) {
                        // pokud se jedná o UPDATE
                        if (cmd === "UPDATE") {
                            // znepřístupnit ixs_ado
                            frm.findFields("ixs_ado").gfield("option", { disabled: true });
                        }
                    };
                    const _implicitniNastaveni = {
                        sloupce: [
                            { coltype: Gordic.Pam.PamColumnType.icon_aktualni, colTemplate: { name: "je_aktualni", caption: "jres:27350173" } }, //RC 27350173 : Aktuální
                            { coltype: Gordic.Pam.PamColumnType.text20, colTemplate: { name: "typ_ado_txt", caption: "jres:27850059" } }, //RC 27850059 : Typ adresy
                            { coltype: Gordic.Pam.PamColumnType.dat_od, colTemplate: { name: "dat_od" } },
                            { coltype: Gordic.Pam.PamColumnType.dat_do, colTemplate: { name: "dat_do" } },
                            { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "obec", caption: "jres:27850051" } }, //RC 27850051 : Obec
                            { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "cast_obce", caption: "jres:27850052" } }, //RC 27850052 : Část obce
                            { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "ulice", caption: "jres:27850053" } }, //RC 27850053 : Ulice
                            { coltype: Gordic.Pam.PamColumnType.text10, colTemplate: { name: "cor", caption: "jres:27850054" } }, //RC 27850054 : Č. or.
                            { coltype: Gordic.Pam.PamColumnType.text10, colTemplate: { name: "cpop", caption: "jres:27850055" } }, //RC 27850055 : Č. pop.
                            { coltype: Gordic.Pam.PamColumnType.text10, colTemplate: { name: "psc", caption: "jres:27850056" } }, //RC 27850056 : PSČ
                            { coltype: Gordic.Pam.PamColumnType.text254, colTemplate: { name: "stat_txt", caption: "jres:27850058" } }, //RC 27850058 : Stát
                            { coltype: Gordic.Pam.PamColumnType.poznamka254, colTemplate: { name: "poznamka" } },
                            { coltype: Gordic.Pam.PamColumnType.dat_zmena, colTemplate: { name: "dat_zmena" } },
                            { coltype: Gordic.Pam.PamColumnType.nazev_rf, colTemplate: { name: "nazev_rf" } },
                            { coltype: Gordic.Pam.PamColumnType.pid, colTemplate: { name: "ixs_ado", caption: "jres:27850360" } }, //RC 27850360 : PID adresy
                        ],
                        editFRM: editFrm,
                        windowsSetting: { width: 700, height: 500 },
                        serverData: {
                            data: {},
                            dtoCallback: _transformDTOcallback,
                            afterOpenFrmCallback: _onOpenFrm,
                        },
                        gridOptions: {
                            showTopPanel: true,
                            showHeaderRow: true,
                            showBottomPanel: false,
                            dataKey: "ixs_ado",
                            selection: (_ev, sel) => {
                                const radek = sel.getSelection()[0];
                                const lzePovolitAkce = radek != null;
                                Content.actions["AdresaHistorie"]?.enabled(lzePovolitAkce);
                                Content.actions["AdresaRefresh"]?.enabled(true);
                                Content.actions["AdresaInsert"]?.enabled(true);
                                Content.actions["AdresaPouzePlatne"]?.enabled(true);
                                Content.actions["AdresaUpdate"]?.enabled(lzePovolitAkce);
                                Content.actions["AdresaDelete"]?.enabled(lzePovolitAkce);
                                Content.actions["AdresaChangeRow"]?.enabled(lzePovolitAkce);
                            }
                        },
                        dataType: Gordic.Pam.DataType.AdresaPAM
                    };
                    super(parentContent, _implicitniNastaveni, userSetting);
                }
            }
            Seznam.Adresy = Adresy;
        })(Seznam = Pam.Seznam || (Pam.Seznam = {}));
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
