var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        var Seznam;
        (function (Seznam) {
            /**
             * Šablona pro zobrazení gridu se seznamem kalendářů
             */
            class Kalendar extends Gordic.Pam.SeznamBase {
                /**
                 * Konstruktor
                 * @param {GContent} parentContent Parent content
                 * @param {IPamSeznamBaseOptions} userSetting Uživatelské nastavení, které přepíše / doplní implicitní nastavení
                 */
                constructor(parentContent, userSetting) {
                    //const Content = parentContent;
                    const editFrm = new Gordic.Forms.Form({ name: "editorKalendare", layoutDescriptor: "L1M1S1" });
                    editFrm
                        .addSection("jres:27850222") //RC 27850222 : Hlavička kalendáře
                        .addRow({ label: "jres:27850219", required: true }) //RC 27850219 : PID kalendáře
                        .addField("gstringbox", "w-4", Gordic.Prefabs.String.ixs(true), {
                        name: "ixs_kal",
                        model: "ixs_kal",
                        disabled: true,
                        validators: [new Gordic.Validators.Required()],
                    })
                        .addRow({ label: "jres:27850179", required: true }) //RC 27850179 : Název
                        .addField("gstringbox", {
                        name: "nazev",
                        model: "nazev",
                        validators: [new Gordic.Validators.Required()],
                    })
                        .addRow({ label: "jres:27850208", required: true }) //RC 27850208 : Typ kalendáře
                        .addField("gselectbox", Gordic.Pam.Prefabs.TypKalendare(parentContent), {
                        dropdown: true,
                        name: "typ_kal",
                        model: "model.typ_kal=value.typ_kal,model.typ_kal_txt=value.typ_kal_txt",
                        validators: [new Gordic.Validators.Required()],
                        initialValue: { typ_kal: 0, typ_kal_txt: 'Veřejný' },
                    })
                        .addRow({ label: "jres:27850207", required: true }) //RC 27850207 : Fond pracovní doby
                        .addField("gselectbox", Gordic.Pam.Prefabs.FondPracovniDoby(parentContent), {
                        dropdown: true,
                        name: "fond_pd",
                        model: "model.fond_pd=value.fond_pd,model.fond_pd_txt=value.fond_pd_txt",
                    })
                        .addRow({ customClass: "hidden" })
                        .addField("gnumberbox", {
                        name: "poc_hodin_kr",
                        model: "poc_hodin_kr",
                    })
                        .addRow({ label: "jres:27350062" }) //RC 27350062 : Poznámka
                        .addField("gstringbox", {
                        name: "poznamka",
                        model: "poznamka",
                    })
                        .addRow({ label: "jres:27850050" }) //RC 27850050 : Datum změny
                        .addField("gdatebox", "w-6", {
                        name: "dat_zmena",
                        model: "dat_zmena",
                        disabled: true,
                        valueType: "datetime"
                    });
                    /**
                     * Callback na transformaci sesbíraného DTO
                     * @param {Gordic.Pam.SeznamBase} seznam objekt, odkud lze získat původní řádek
                     * @param {Object} dataFormulare data ze zadávacího formuláře
                     * @param {Object} _serverData data zaslaná ze serveru (tímto způsobem lze dodat konstanty mimo formuláře)
                     * @param {string} cmd příkaz, který se vykonává INSERT, UPDATE ...
                     * @returns {Object} objekt s transformovanými daty
                     */
                    const _transformDTOcallback = function (seznam, dataFormulare, _serverData, cmd) {
                        // převzít data z formuláře
                        const result = dataFormulare;
                        // vybraný řádek
                        const radek = seznam.SelectedRow;
                        // období z přihlášení
                        //result.rok_obd_mzdy = rok_obd_mzdy; 
                        //result.rok = RokObdMzdy2Rok(rok_obd_mzdy);
                        //result.obd_mzdy = RokObdMzdy2Mesic(rok_obd_mzdy);
                        // transformace pro jednotlivé typy akcí
                        switch (cmd) {
                            case "INSERT":
                                if (result.poznamka == "" || !result.poznamka) { // v případě prázdné poznámky
                                    result.poznamka = "Záznam vytvořen " + Gordic.Pam.NormalizedTimestampPoznamka();
                                }
                                if (!result.per_len) { // není vyplněno na frm
                                    result.per_len = 7; // Uchovaná délka periody z generátoru dní
                                }
                                if (!result.per_fond) { // není vyplněno na frm
                                    result.per_fond = new Decimal(40); // Uchovaný hodinový fond jedné periody z generátoru dní
                                }
                                if (!result.poc_hodin_kr) { // není vyplněno na frm
                                    result.poc_hodin_kr = new Decimal(1); // Číslo, kterým je dělena doba v pamdkal.hod_den za účelem získání skutečného denního fondu
                                }
                                if (!result.per_distr) { // není vyplněno na frm
                                    result.per_distr = "-";
                                }
                                if (!result.pouzit_svatky) { // není vyplněno na frm
                                    result.pouzit_svatky = 1;
                                }
                                result.aktivita = 100;
                                break;
                            case "UPDATE":
                                // povinné hodnoty
                                if (!result.per_len) { // není vyplněno
                                    result.per_len = radek == null ? 7 : radek.per_len; // Uchovaná délka periody z generátoru dní
                                }
                                if (!result.per_fond) { // není vyplněno
                                    result.per_fond = radek == null ? new Decimal(40) : radek.per_fond; // Uchovaný hodinový fond jedné periody z generátoru dní
                                }
                                if (!result.poc_hodin_kr) { // není vyplněno
                                    result.poc_hodin_kr = radek == null ? new Decimal(1) : radek.poc_hodin_kr; // Číslo, kterým je dělena doba v pamdkal.hod_den za účelem získání skutečného denního fondu
                                }
                                if (!result.per_distr) { // není vyplněno
                                    result.per_distr = radek == null ? "-" : radek.per_distr;
                                }
                                if (!result.pouzit_svatky) { // není vyplněno na frm
                                    result.pouzit_svatky = 1;
                                }
                                result.aktivita = 100;
                                break;
                            case "DELETE":
                                result.aktivita = 900;
                                break;
                        }
                        return result;
                    };
                    /**
                    * Callback po vytvoření formuláře
                    * @param {Gordic.Pam.SeznamBase} seznam SeznamBase
                    * @param {GContent} cnt content
                    * @param {GForm} frm formulář
                    * @param {IPamSeznamBaseCommand} cmd, příkaz, který se vykonává INSERT, UPDATE ...
                    * @param {any} data získaná pomocí waitForValues
                    * @returns objekt s transformovanými daty
                    */
                    const _onOpenFrm = function (seznam, cnt, frm, cmd, data) {
                        if (cmd == 'UPDATE') { // editace
                            // zneaktivnit pole Typ kalendáře
                            frm.findFields("typ_kal").gfield("option", { disabled: true });
                        }
                    };
                    const _implicitniNastaveni = {
                        sloupce: [
                            { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "nazev", caption: "jres:27850181" } }, //RC 27850181 : Název
                            { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "typ_kal_txt", caption: "jres:27850208" } }, //RC 27850208 : Typ kalendáře
                            { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: "fond_pd_txt", caption: "jres:27850207" } }, //RC 27850207 : Fond pracovní doby
                            { coltype: Gordic.Pam.PamColumnType.poznamka50, colTemplate: { name: "poznamka" } },
                            { coltype: Gordic.Pam.PamColumnType.dat_zmena, colTemplate: { name: "dat_zmena" } },
                        ],
                        editFRM: editFrm,
                        windowsSetting: { width: 600, height: 450 },
                        serverData: {
                            dtoCallback: _transformDTOcallback,
                            afterOpenFrmCallback: _onOpenFrm
                        },
                        gridOptions: {
                            showTopPanel: true,
                            showHeaderRow: true,
                            showBottomPanel: true,
                            dataKey: "ixs_kal",
                            defaultProfile: {
                                sort: "nazev,ixs_kal"
                            }
                        },
                        dataType: Gordic.Pam.DataType.KalendarHlavicka
                    };
                    super(parentContent, _implicitniNastaveni, userSetting);
                }
            }
            Seznam.Kalendar = Kalendar;
        })(Seznam = Pam.Seznam || (Pam.Seznam = {}));
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        Gordic.Pam.Seznam.KalendarDny.ts                               </Name>
//    <Description> Šablona pro zobrazení gridu se seznamem kalendářů           </Description>
//    <Author>      Radim Dušek                                                 </Author>
