                        const dtoServer = await Gordic.Isl.PamPpvMesicniZmena.prepocitejFormular({ data: dto }).getData();
                        // přiřadit DTO z odpovědi serveru do DTO, které se vrací z této funkce
                        Object.assign(dto, dtoServer);
