//    <Name>        Gordic.Pam.WebControls.Nzzn.ts                            </Name>
//    <Description> Šablona pro zobrazení gridu se seznamem NZŽN              </Description>
//    <Author>      Radim Dušek                                                 </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2025                            </Copyright>
//    <Created>     2025-09-15                                                  </Created>
