                    //data jako parametry seznamu
                    const serverData = userSetting?.serverData?.data;
                    const rok_obd_mzdy = (serverData && serverData["rok_obd_mzdy"]) ? serverData["rok_obd_mzdy"] : "";
                    const rok = Pam.RokObdMzdy2Rok(rok_obd_mzdy);
                    const datOdMes = Pam.RokObdMzdy2FirstDay(rok_obd_mzdy);
                    const datDoMes = Pam.RokObdMzdy2LastDay(rok_obd_mzdy);
                    const ico = (serverData && serverData["ico"]) ? serverData["ico"] : "";
                    const frm = new Gordic.Forms.Form({ name: "editorCizichUctu", layoutDescriptor: "L1M1S1" });
                    frm
