var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        var Seznam;
        (function (Seznam) {
            /**
            * Šablona pro zobrazení gridu se seznamem vynětí
            */
            class Vyneti extends Gordic.Pam.SeznamBase {
                /**
                 * Konstruktor
                 * @param {GContent} parentContent Parent content
                 * @param {IPamSeznamBaseOptions} userSetting Uživatelské nastavení, které přepíše / doplní implicitní nastavení
                 */
                constructor(parentContent, userSetting) {
                    const Content = parentContent;
                    const editFrm = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1" });
                    editFrm
                        .addSection()
                        .addRow({ label: "jres:27850140", required: true }) //RC 27850140 : Pracovní poměr
                        .addField("gstringbox", {
                        name: "ixs_ppv",
                        model: "ixs_ppv",
                        disabled: true,
                        initialValue: () => {
                            return this.ServerData["ixs_ppv"];
                        },
                    })
                        .addRow({ label: "jres:27350060", required: true }) //RC 27350060 : Platnost
                        .addField("gdatebox", "w-6", {
                        name: "dat_od",
                        model: "dat_od",
                        initialValue: Pam.RokObdMzdy2FirstDay(PAM_CACHE.rokobdlogin), // výchozí hodnota - první den z rok_obd_mzdy
                        valueType: "date",
                        validators: [
                            new Gordic.Validators.Required(),
                            new Gordic.Validators.Base({
                                message: "jres:27850321", //RC 27850321 : Pole Platnost od musí být menší nebo rovno poli Platnost do
                                validate: (value, source) => {
                                    // při nezadání hodnoty zabere validátor Required
                                    if (value === null)
                                        return true;
                                    // hodnota z pole
                                    const datOd = value;
                                    // hodnota z pole Platnost do, pokud je null, pak 31.12.2999
                                    const datDo = $(source).closest(".gform").findFields("dat_do").gfield("getValue") ?? Pam.RokObdMzdy2LastDay(35999);
                                    return datOd <= datDo;
                                }
                            }),
                        ]
                    })
                        .addField("gdatebox", "w-6", {
                        name: "dat_do",
                        model: "dat_do",
                        valueType: "date",
                        initialValue: Pam.RokObdMzdy2LastDay(35999), // výchozí hodnota poslední den z 35999, tzn. 31.12.2999
                        formatter: (value, editMode) => { if (!value)
                            return ""; return value.getFullYear() === 2999 ? "" : Gordic.Templates.Formatters.date(value); }, // skrývání 2999
                        validators: [
                            new Gordic.Validators.Required(),
                            new Gordic.Validators.Base({
                                message: "jres:27850323", //RC 27850323 : Pole Platnost do musí být větší nebo rovno poli Platnost od
                                validate: (value, source) => {
                                    // při nezadání hodnoty zabere validátor Required
                                    if (value === null)
                                        return true;
                                    // hodnota z pole Platnost od
                                    const datOd = $(source).closest(".gform").findFields("dat_od").gfield("getValue");
                                    // hodnota z pole, pokud je null, pak 31.12.2999
                                    const datDo = Pam.toDate(value) ?? Pam.RokObdMzdy2LastDay(35999);
                                    return datDo >= datOd;
                                }
                            }),
                        ]
                    })
                        .addRow({ label: "jres:27850414" }) //RC 27850414 : Druh vynětí
                        .addField("gselectbox", Gordic.Pam.Prefabs.DruhVyneti(Content), {
                        name: "druh_vyneti",
                        model: "model.druh_vyneti=value.druh_vyneti",
                        validators: [new Gordic.Validators.Required()]
                    })
                        .addRow({ label: "jres:27350062" }) //RC 27350062 : Poznámka
                        .addField("gstringbox", {
                        name: "poznamka",
                        model: "poznamka",
                    })
                        .addRow({ label: "jres:27850050" }) //RC 27850050 : Datum změny
                        .addField("gdatebox", "w-6", {
                        name: "dat_zmena",
                        model: "dat_zmena",
                        disabled: true,
                        valueType: "datetime"
                    });
                    /**
                     * Callback na transformaci sesbíraného DTO
                    * @param {Gordic.Pam.SeznamBase} seznam objekt, odkud lze získat původní řádek
                    * @param {Object} dataFormulare data ze zadávacího formuláře
                    * @param {Object} serverData data zaslaná ze serveru (tímto způsobem lze dodat konstanty mimo formuláře)
                    * @param {string} cmd příkaz, který se vykonává INSERT, UPDATE ...
                    * @returns {Object} objekt s transformovanými daty
                    */
                    const _transformDTOcallback = function (seznam, dataFormulare, serverData, cmd) {
                        const result = dataFormulare;
                        const radek = seznam.SelectedRow; // z vybraného řádku
                        // není součástí formuláře
                        result.ixs_ppv = serverData["ixs_ppv"];
                        // transformace pro jednotlivé typy akcí
                        switch (cmd) {
                            case "INSERT":
                                result.poznamka = Pam.NVL(result.poznamka, Pam.sestavPoznamku("Vytvořeno"));
                                result.aktivita = 100;
                                break;
                            case "UPDATE":
                                result.aktivita = 100;
                                break;
                            case "DELETE":
                                result.aktivita = 900;
                                break;
                            case "KONTROLA":
                                break;
                        }
                        return result;
                    };
                    /**
                    * Callback po vytvoření formuláře
                    * @param {Gordic.Pam.SeznamBase} _seznam SeznamBase
                    * @param {GContent} _cnt content
                    * @param {GForm} frm formulář
                    * @param {IPamSeznamBaseCommand} cmd, příkaz, který se vykonává INSERT, UPDATE ...
                    * @param {any} data získaná pomocí waitForValues
                    * @returns objekt s transformovanými daty
                    */
                    const _onOpenFrm = function (_seznam, _cnt, frm, cmd, data) {
                        // pokud se jedná o UPDATE
                        if (cmd === "UPDATE") {
                            // znepřístupnit ixs_ado
                            frm.findFields("dat_od").gfield("option", { disabled: true });
                        }
                    };
                    const _implicitniNastaveni = {
                        sloupce: [
                            { coltype: Gordic.Pam.PamColumnType.icon_aktualni, colTemplate: { name: "je_aktualni", caption: "jres:27850404" } }, //RC 27850404 : Aktuální
                            { coltype: Gordic.Pam.PamColumnType.text, colTemplate: { name: "druh_vyneti_pam_txt", caption: "jres:27850405" } }, //RC 27850405 : Druh vynětí PAM
                            { coltype: Gordic.Pam.PamColumnType.text, colTemplate: { name: "druh_vyneti_per_txt", caption: "jres:27850406" } }, //  //RC 27850406 : Druh vynětí PER
                            { coltype: Gordic.Pam.PamColumnType.dat_od, colTemplate: { name: "dat_od" } },
                            { coltype: Gordic.Pam.PamColumnType.dat_do, colTemplate: { name: "dat_do" } },
                            { coltype: Gordic.Pam.PamColumnType.smallint, colTemplate: { name: "slozka_mzdy", caption: "jres:27850407" } }, //RC 27850407 : Složka
                            { coltype: Gordic.Pam.PamColumnType.nazev_slozky, colTemplate: { name: "slozka_mzdy_txt" } },
                            { coltype: Gordic.Pam.PamColumnType.dat_od, colTemplate: { name: "dat_od_sl", caption: "jres:27850408" } }, //RC 27850408 : Složka od
                            { coltype: Gordic.Pam.PamColumnType.dat_do, colTemplate: { name: "dat_do_sl", caption: "jres:27850409" } }, //RC 27850409 : Složka do
                            { coltype: Gordic.Pam.PamColumnType.text, colTemplate: { name: "zdroj_txt", caption: "jres:27850410" } }, //RC 27850410 : Původ
                            { coltype: Gordic.Pam.PamColumnType.poznamka50, colTemplate: { name: "poznamka" } },
                        ],
                        editFRM: editFrm,
                        windowsSetting: { width: 700, height: 500 },
                        serverData: {
                            data: {},
                            dtoCallback: _transformDTOcallback,
                            afterOpenFrmCallback: _onOpenFrm,
                        },
                        gridOptions: {
                            showTopPanel: true,
                            showHeaderRow: true,
                            showBottomPanel: false,
                            dataKey: "ixs_ado",
                            //selection: (_ev, sel) => {
                            //    const radek = sel.getSelection()[0];
                            //    const existujeRadek = radek != null;
                            //    
                            //    Content.actions["VynetiRefresh"]?.enabled(true);
                            //    Content.actions["VynetiPouzePlatne"]?.enabled(true);
                            //    Content.actions["VynetiInsert"]?.enabled(true);
                            //    Content.actions["VynetiUpdate"]?.enabled(existujeRadek);
                            //    Content.actions["VynetiDelete"]?.enabled(existujeRadek);
                            //    Content.actions["VynetiChangeRow"]?.enabled(existujeRadek);
                            //    Content.actions["VynetiHistorie"]?.enabled(existujeRadek);
                            //    
                            //}
                        },
                        dataType: Gordic.Pam.DataType.Vyneti
                    };
                    super(parentContent, _implicitniNastaveni, userSetting);
                }
            }
            Seznam.Vyneti = Vyneti;
        })(Seznam = Pam.Seznam || (Pam.Seznam = {}));
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
