                            Content.findForms("testForm").findFields().gfield("model", "collect", dto);
                            const dataTmp = Pam.dumpObj(dto); // naformátování výsledku do podoby abych mohl plnit grid
                            const data = [];
                            for (const klic in dataTmp) {
                                if (dataTmp.hasOwnProperty(klic))
                                    data.push({ model: Pam.toString(klic).trim(), value: Pam.toString(dataTmp[klic]).trim() });
                            }
                            const optDialog = { width: 450, height: 600, title: "Data formuláře" };
                            let frm = new Gordic.Forms.Form()
                                .addField("ggrid", { layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" }, {
                                data: data,
                                columns: new Gordic.Pam.Columns().SestavSloupce([
                                    { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: 'model' } },
                                    { coltype: Gordic.Pam.PamColumnType.text50, colTemplate: { name: 'value' } }
                                ])
                            });
                            Gordic.Pam.Forms.prototype.WindowFromFrm(frm, optDialog, Content);
